// Chaves reais na tabela configuracoes:
//   cliente   → preco_dinamico / preco_dinamico_ativado_em
//   entregador → preco_dinamico_entregador / preco_dinamico_entregador_ativado_em
function _pdChave(tipo){return tipo==='cliente'?'preco_dinamico':`preco_dinamico_${tipo}`;}
function _pdChaveTs(tipo){return tipo==='cliente'?'preco_dinamico_ativado_em':`preco_dinamico_${tipo}_ativado_em`;}
let _pdCidades={}; // {cidade: {valor, ativado_em}}
let _pdCidadesEnt={}; // {cidade: {valor, ativado_em}}
let _pdCidadesAplicaveis={}; // {cidade: [loja_id,...]}
let _pdCidadesAplicaveisEnt={}; // {cidade: [motoboy_id,...]}
let _pdCidTimers={}; // keyed by `${tipo}_${cidade}`
function _cidadeSufixo(c){return{'Ribeirão Preto':'RP','São José dos Campos':'SJC','Campinas':'CAMPI'}[c]||'';}

// ── BRASÍLIA TIMEZONE HELPERS ──
// ⚠️ NÃO REVERTER O FALLBACK '-03:00' ABAIXO SEM REFAZER O TESTE DESCRITO
// AQUI — já foi revertido por engano uma vez, não repete.
//
// Se a string já vem com offset explícito ('Z' ou +/-HH:MM), é uma coluna
// timestamptz de verdade (creditos_lojas, cobrancas_lojas, saques,
// creditos_entregadores) — usa como está. Sem offset, é uma das colunas
// confirmadas timestamp SEM fuso (pedidos.*, entregadores.updated_at,
// lojas.created_at — ver comentário perto de _inicioDiaBrasilia) cujo
// valor já É hora local de Brasília — assume -03:00, não 'Z'/UTC.
//
// Histórico (pra não reverter de novo sem motivo):
//   1ª tentativa: trocou 'Z' por '-03:00'. Usuário reportou que o horário
//     de um pedido do meio do dia (#005) já estava certo ANTES da
//     mudança — revertido de volta pra 'Z'.
//   Investigação seguinte: esse reporte era sobre o APP FLUTTER (outro
//     repositório, não editado aqui), não sobre o painel web. Não provava
//     nada sobre o painel.
//   Prova real (produção, painel web): filtro do Relatório de Entregas
//     em 01/08/2026 trouxe pedidos #7774 e #2061 exibidos como
//     "31/07/2026 21:03"/"21:01" — 3h ATRASADO. Query direta no banco
//     confirmou created_at real = 2026-08-01 00:03:00 / 00:01:50 (minuto
//     a minuto batendo com a previsão de -3h do fallback 'Z' errado).
//     Um pedido de virada de meia-noite é o único caso que expõe o bug
//     de forma óbvia (muda a DATA exibida, não só a hora) — por isso o
//     teste com pedido do meio do dia não pegou da primeira vez.
const _parseUtc=(s)=>{const t=String(s).trim().replace(' ','T');return new Date(/Z|[+-]\d{2}:?\d{2}$/.test(t)?t:t+'-03:00');};
const toBrasilia=(dataStr)=>{if(!dataStr)return null;return new Date(_parseUtc(dataStr).toLocaleString('en-US',{timeZone:'America/Sao_Paulo'}));};
const formatarHora=(dataStr)=>{if(!dataStr)return'—';return _parseUtc(dataStr).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'});};
// Badge "⚡ Saída até HH:MM" (card de pedido, Mapa ao Vivo) — sempre
// created_at + 15min. _parseUtc já trata created_at (sem fuso, dígitos
// já em Brasília) corretamente, então dá pra somar minutos direto no
// timestamp real sem cair no bug de +3h já documentado nesse arquivo.
const _saidaAte=(dataStr)=>{if(!dataStr)return null;return new Date(_parseUtc(dataStr).getTime()+15*60000).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'});};
const formatarDataHora=(dataStr)=>{if(!dataStr)return'—';return _parseUtc(dataStr).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});};
const formatarData=(dataStr)=>{if(!dataStr)return'—';return _parseUtc(dataStr).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'});};
function formatarDataBR(data){if(!data)return'—';if(typeof data==='string'){const m=data.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return`${m[3]}/${m[2]}/${m[1]}`;}const d=data instanceof Date?data:new Date(data);if(isNaN(d))return'—';return d.toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric'});}
const _dataHojeBrasilia=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});
// Badge "Agendado": mostra só a hora quando o agendamento é hoje (comportamento
// original), mas inclui DD/MM quando é outro dia — senão um pedido agendado
// pra amanhã/semana que vem aparece com hora sem contexto de data nenhum.
const formatarAgendado=(dataStr)=>{
  if(!dataStr)return'—';
  const d=_parseUtc(dataStr);
  const hora=d.toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'});
  const dataAgend=d.toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});
  if(dataAgend===_dataHojeBrasilia())return hora;
  const[,mm,dd]=dataAgend.split('-');
  return`${dd}/${mm} ${hora}`;
};
// Timestamp "agora" pras colunas timestamp SEM fuso (pedidos.created_at/
// updated_at/finalizado_em/pronto_em/aceito_em/em_rota_em, entregadores.
// updated_at, lojas.created_at — mesma lista do comentário "REGRA DE FUSO"
// abaixo). new Date().toISOString() é UTC com 'Z' — errado pra essas
// colunas, que esperam os dígitos já em hora local de Brasília, sem
// offset (o valor É a hora de parede de Brasília, guardado como texto).
// Bug real encontrado em produção: no INSERT de pedido, tanto mandar
// toISOString() quanto OMITIR created_at (contando com o DEFAULT now() da
// coluna) gravava dígitos de UTC — o DEFAULT da coluna cai pro fuso da
// sessão do Postgres (UTC), não Brasília. #003/#3462 confirmados
// gravados 3h à frente do relógio real (14:19 gravado quando eram 11:19
// em Brasília). NUNCA usar .toISOString() nem confiar no DEFAULT da
// coluna pra essas colunas específicas — sempre mandar _agoraBrasilia()
// explicitamente.
const _agoraBrasilia=()=>{
  const d=new Date();
  const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).formatToParts(d).map(x=>[x.type,x.value]));
  return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}.${String(d.getMilliseconds()).padStart(3,'0')}`;
};
const _lojaFiltro=()=>currentPerfil==='loja'&&currentUser?.loja_id?`&loja_id=eq.${currentUser.loja_id}`:'';
// Igual a _lojaFiltro(), mas pra usar direto na tabela lojas — ela não tem
// coluna loja_id, a própria chave é id.
const _lojaFiltroId=()=>currentPerfil==='loja'&&currentUser?.loja_id?`&id=eq.${currentUser.loja_id}`:'';
// ⚠️ REGRA DE FUSO — LER ANTES DE MEXER EM QUALQUER FILTRO DE DATA/HORA.
// Confirmado via information_schema (ver migrations/add_pedidos_finalizados_por_mes_rpc.sql)
// e via inspeção direta de valores reais retornados pela API (presença/ausência
// de offset '+00:00' na resposta — confirmado de novo 2026-08-14, bug do
// horário +3h nos pedidos):
//   pedidos.created_at / updated_at / finalizado_em / pronto_em / aceito_em /
//   em_rota_em / pagamento_confirmado_em,
//   entregadores.created_at / updated_at, lojas.created_at
// são `timestamp` SEM fuso e o valor gravado JÁ É hora local de Brasília.
// lojas.updated_at e pedidos.agendado_para são DIFERENTES — timestamptz de
// verdade (confirmado com offset '+00:00' na resposta — agendado_para
// causou um bug real em produção, pedido #3919 salvo 3h antes do horário
// escolhido, quando foi tratado como se fosse sem fuso igual as outras
// colunas de pedidos — CUIDADO, é fácil generalizar demais essa lista só
// por estar na mesma tabela). Tratar como as tabelas timestamptz abaixo:
// new Date(valorDoInput).toISOString() pra gravar, _parseUtc/formatarHora
// pra ler (que já detectam o offset e funcionam certo sem mudança nenhuma).
//
// NUNCA gravar new Date().toISOString() (UTC com 'Z') nessas colunas, e
// NUNCA confiar no DEFAULT now() da coluna pra elas — os dois caem pro
// fuso da sessão do Postgres (UTC), gravando os dígitos errados (3h à
// frente do relógio real de Brasília). Sempre mandar _agoraBrasilia()
// explicitamente no INSERT/UPDATE. Ler valores dessas colunas sempre via
// _parseUtc/formatarHora/formatarDataHora (não _tsUtc — esse assume UTC
// pra string sem offset, o oposto do que essas colunas precisam).
// NUNCA aplicar AT TIME ZONE (SQL) nem _inicioDiaBrasilia/_fimDiaBrasilia ou
// qualquer conversão -03:00 nessas colunas — compare a string local direto
// (ex: `${data}T00:00:00`), igual pedidos_finalizados_por_mes faz.
//
// Já creditos_lojas, creditos_entregadores, cobrancas_lojas e saques são
// `timestamptz` de verdade e PRECISAM da conversão normal — é pra essas que
// _inicioDiaBrasilia/_fimDiaBrasilia abaixo servem.
const _inicioDiaBrasilia=(s)=>new Date(s+'T00:00:00-03:00').toISOString();
const _fimDiaBrasilia=(s)=>new Date(s+'T23:59:59.999-03:00').toISOString();
// Comparado direto (string) contra pedidos.created_at, que é timestamp SEM
// fuso — por isso NÃO passa por _inicioDiaBrasilia aqui (isso mandaria um
// boundary UTC +3h, travando pedidos da própria semana como "anteriores").
// _normDataLocal abaixo cobre o separador (espaço vs 'T') que a API pode
// devolver, pra comparação de string continuar válida nos dois formatos.
const _inicioSemanaAtualBrasilia=()=>{const _h=_dataHojeBrasilia();const [_y,_m,_d]=_h.split('-').map(Number);const _dow=new Date(Date.UTC(_y,_m-1,_d)).getUTCDay();const _diff=_dow===0?6:_dow-1;return `${new Date(Date.UTC(_y,_m-1,_d-_diff)).toISOString().slice(0,10)}T00:00:00`;};
const _normDataLocal=(s)=>String(s||'').replace(' ','T');

// ── FATURAS — VENCIMENTO/JUROS/BLOQUEIO ──
// Vencimento de uma cobrança (fatura) = quarta-feira da semana de geração
// (mesma semana se gerada até quarta, senão a quarta da semana seguinte),
// sempre derivado de cobrancas_lojas.created_at — nunca persistido, porque
// created_at não muda depois de criado, então recalcular sempre dá o mesmo
// resultado (mesmo espírito do "calcula na hora" pedido pro juros/multa).
// created_at é timestamptz de verdade (comentário no topo deste bloco de
// helpers de fuso) — _parseUtc já entende o offset explícito.
// Cálculo por data-calendário pura (Date.UTC), igual _inicioSemanaAtualBrasilia
// — Brasil não observa horário de verão desde 2019, então não há ambiguidade
// de fuso em aritmética de dia-a-dia como essa.
const _dataYMDBrasilia=(dataStr)=>_parseUtc(dataStr).toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});
function _faturaVencimentoYMD(cobranca){
  const [y,m,d]=_dataYMDBrasilia(cobranca.created_at).split('-').map(Number);
  const dow=new Date(Date.UTC(y,m-1,d)).getUTCDay(); // 0=Dom..6=Sáb, 3=Qua
  const diasAteQuarta=dow<=3?3-dow:10-dow; // gerada Qui/Sex/Sáb vence só na quarta da semana seguinte
  return new Date(Date.UTC(y,m-1,d+diasAteQuarta)).toISOString().slice(0,10);
}
// >0 = dias em atraso (vencimento já passou), 0 = vence hoje, <0 = ainda não venceu.
function _diasAtrasoFatura(vencYMD){
  const [vy,vm,vd]=vencYMD.split('-').map(Number);
  const [hy,hm,hd]=_dataHojeBrasilia().split('-').map(Number);
  return Math.round((Date.UTC(hy,hm-1,hd)-Date.UTC(vy,vm-1,vd))/86400000);
}
// Regra de atraso (2026-10-02): multa única = o MAIOR entre 5% do valor
// original e R$ 5,00; juros = 0,3% ao dia sobre o valor original, por dia
// corrido desde o vencimento. Os dois começam no dia seguinte ao vencimento
// (dataAtraso===0, vence hoje, ainda sem multa/juros). Substitui a regra
// anterior (multa 2% + juros 10%/mês = 0,333%/dia, e taxa fixa de R$ 5 sem
// juros para fatura < R$ 100). Fatura já paga não passa por aqui: o valor
// fica congelado em valor_pago_final na aprovação.
const FATURA_MULTA_PCT=0.05,FATURA_MULTA_MIN=5,FATURA_JUROS_DIA=0.003;
function _calcularJurosMultaFatura(valorOriginal,vencYMD){
  const diasAtraso=Math.max(0,_diasAtrasoFatura(vencYMD));
  const valOrig=parseFloat(valorOriginal)||0;
  if(diasAtraso<=0)return{diasAtraso:0,multa:0,juros:0,taxaFixa:0,valorAtualizado:Math.round(valOrig*100)/100};
  const multa=Math.max(Math.round(valOrig*FATURA_MULTA_PCT*100)/100,FATURA_MULTA_MIN);
  const juros=Math.round(valOrig*FATURA_JUROS_DIA*diasAtraso*100)/100;
  return{diasAtraso,multa,juros,taxaFixa:0,valorAtualizado:Math.round((valOrig+multa+juros)*100)/100};
}
// Carrega a(s) cobrança(s) pendente(s) da loja logada e escolhe a mais
// urgente (maior atraso) pra representar no botão "Criar Entrega" e no
// banner da tela Mapa — chamada no login, na restauração de sessão e
// periodicamente pelo ciclo do banner (ver _iniciarFaturaBannerLoja),
// pra refletir sem reload quando o admin aprova o pagamento em outra sessão.
async function _carregarFaturaAtualLoja(){
  if(currentPerfil!=='loja'||!currentUser?.loja_id){_faturaAtualLoja=null;_faturaVencidaLoja=false;return;}
  const rows=await db('cobrancas_lojas','GET',null,`?loja_id=eq.${currentUser.loja_id}&status=eq.pendente&order=created_at.desc`).catch(()=>[]);
  const pendentes=Array.isArray(rows)?rows:[];
  if(!pendentes.length){_faturaAtualLoja=null;_faturaVencidaLoja=false;_atualizarBtnCriarEntrega();return;}
  const anotadas=pendentes.map(c=>{const vencYMD=_faturaVencimentoYMD(c);return{...c,_vencYMD:vencYMD,_diasAtraso:_diasAtrasoFatura(vencYMD)};});
  anotadas.sort((a,b)=>b._diasAtraso-a._diasAtraso);
  _faturaAtualLoja=anotadas[0];
  _faturaVencidaLoja=anotadas.some(c=>c._diasAtraso>=1);
  _atualizarBtnCriarEntrega();
}
// Ciclo só se aplica ao estado "fatura aberta" (ainda não venceu) — "vence
// hoje" e "vencida" ficam fixos (ver _tickFaturaBanner).
const _FATURA_BANNER_CICLO_MS=60*60*1000; // aparece a cada 1h
const _FATURA_BANNER_VISIVEL_MS=10*60*1000; // fica 10min visível por ciclo
// Um único setInterval global (iniciado no login/restauração de sessão, não
// a cada render do Mapa) — sobrevive a troca de aba porque só toca o DOM se
// #alerta-fatura-loja existir na tela atual; troca de aba não recria nem
// duplica o timer. elapsed%CICLO em vez de setTimeout encadeado: não
// acumula drift nem timers extras se a loja deixar a aba aberta por horas.
function _iniciarFaturaBannerLoja(){
  if(currentPerfil!=='loja')return;
  clearInterval(_faturaBannerTickInterval);clearInterval(_faturaBannerRefreshInterval);
  _faturaBannerCycleStart=Date.now();
  _faturaBannerFechada=false;
  _carregarFaturaAtualLoja().then(_tickFaturaBanner);
  _faturaBannerTickInterval=setInterval(_tickFaturaBanner,15000);
  _faturaBannerRefreshInterval=setInterval(_carregarFaturaAtualLoja,5*60*1000);
}
function _tickFaturaBanner(){
  const el=document.getElementById('alerta-fatura-loja');
  if(!el)return;
  if(!_faturaAtualLoja){el.style.display='none';return;}
  // Só o estado "fatura aberta" (diasAtraso<0, ainda não venceu) entra no
  // ciclo aparece/some (10min/1min) — "vence hoje" (diasAtraso===0) e
  // "vencida" (diasAtraso>=1) ficam fixos na tela até a fatura ser paga
  // (não têm botão de fechar — só some quando o admin aprova o pagamento).
  if(_faturaAtualLoja._diasAtraso<0){
    if(_faturaBannerFechada){el.style.display='none';return;}
    const elapsed=(Date.now()-_faturaBannerCycleStart)%_FATURA_BANNER_CICLO_MS;
    if(elapsed>=_FATURA_BANNER_VISIVEL_MS){el.style.display='none';return;}
  }
  const titulo=document.getElementById('alerta-fatura-loja-titulo');
  if(titulo)titulo.textContent=_faturaAtualLoja._diasAtraso>=1
    ?'🚫 Fatura vencida! Regularize o pagamento para continuar criando entregas.'
    :_faturaAtualLoja._diasAtraso===0
    ?'⏰ Sua fatura vence hoje 18:00. Evite atrasos no pagamento.'
    :'🧾 Fatura Em Aberto. Clique Para Ver A Fatura.';
  // Botão de fechar só no estado "aberta" (ainda não venceu) — "vence hoje"
  // e "vencida" não podem ser dispensados pela loja, só desaparecem quando
  // a fatura é paga/aprovada.
  const fecharBtn=document.getElementById('alerta-fatura-loja-fechar');
  if(fecharBtn)fecharBtn.style.display=_faturaAtualLoja._diasAtraso<0?'flex':'none';
  el.style.display='flex';
}
function _fecharAlertaFaturaLoja(){
  _faturaBannerFechada=true;
  const el=document.getElementById('alerta-fatura-loja');
  if(el)el.style.display='none';
}

// ── CHAT INTERNO LOJA <-> ADMIN/SUPORTE ──
// mensagens_chat.created_at é timestamptz de verdade (default now()) —
// formatarHora/formatarDataHora (helpers de fuso do topo do arquivo) já
// lidam com isso direto, sem precisar de nenhuma conversão extra.
async function _carregarBadgeChatLoja(){
  if(currentPerfil!=='loja'||!currentUser?.loja_id)return;
  const rows=await db('mensagens_chat','GET',null,`?loja_id=eq.${currentUser.loja_id}&remetente_perfil=neq.loja&lida=eq.false&select=id`).catch(()=>[]);
  _chatNaoLidasLojaCount=Array.isArray(rows)?rows.length:0;
  const badge=document.getElementById('chat-badge-loja');
  if(!badge)return;
  if(_chatNaoLidasLojaCount>0){badge.textContent=_chatNaoLidasLojaCount>9?'9+':_chatNaoLidasLojaCount;badge.style.display='flex';}
  else badge.style.display='none';
}
function _iniciarChatBadgeLoja(){
  if(currentPerfil!=='loja')return;
  clearInterval(_chatBadgeInterval);
  _carregarBadgeChatLoja();
  _chatBadgeInterval=setInterval(_carregarBadgeChatLoja,20000);
}
// Mesma ideia de _carregarBadgeChatLoja, mas pro lado admin/suporte: conta
// não lidas de TODAS as lojas E entregadores (sem filtro de loja_id/
// entregador_id), já que aqui o botão flutuante único cobre a caixa de
// entrada inteira, não uma conversa só.
async function _carregarBadgeChatAdmin(){
  if(currentPerfil==='loja')return;
  const rows=await db('mensagens_chat','GET',null,'?remetente_perfil=in.(loja,entregador)&lida=eq.false&select=id,remetente_perfil').catch(()=>[]);
  const lista=Array.isArray(rows)?rows:[];
  _chatNaoLidasAdminCount=lista.length;
  const badge=document.getElementById('chat-badge-admin');
  if(badge){
    if(_chatNaoLidasAdminCount>0){badge.textContent=_chatNaoLidasAdminCount>9?'9+':_chatNaoLidasAdminCount;badge.style.display='flex';}
    else badge.style.display='none';
  }
  // Alerta sonoro pra mensagem nova de ENTREGADOR (item 7 do chat Parceiro
  // Let's Go) — reaproveita tocarSomPronto(), o mesmo som já usado pra
  // "pedido pronto". Mesmo padrão de idsProntoNotificados: só toca uma vez
  // por mensagem, não a cada poll de 20s enquanto ela continuar não lida.
  lista.filter(m=>m.remetente_perfil==='entregador').forEach(m=>{
    if(!_chatMsgEntregadorNotificadas.has(m.id)){
      _chatMsgEntregadorNotificadas.add(m.id);
      tocarSomPronto();
    }
  });
}
function _iniciarChatBadgeAdmin(){
  if(currentPerfil==='loja')return;
  clearInterval(_chatBadgeInterval);
  _carregarBadgeChatAdmin();
  _chatBadgeInterval=setInterval(_carregarBadgeChatAdmin,20000);
}
function _bolhaChatHtml(m){
  const souLoja=currentPerfil==='loja';
  // Generalizado pra 3 remetente_perfil possíveis agora (loja/entregador/
  // adm/suporte) — achado real na auditoria: a versão antiga
  // ('!==loja' = "é minha") tratava mensagem do PRÓPRIO entregador como se
  // fosse do admin (bolha do lado errado) assim que 'entregador' virou um
  // valor possível. Só quem vê esse chat é loja (sua própria conversa) ou
  // adm/suporte (qualquer conversa) — entregador nunca abre essa tela.
  const minhaMsg=souLoja?m.remetente_perfil==='loja':(m.remetente_perfil==='adm'||m.remetente_perfil==='suporte');
  const nomeExibido=m.remetente_perfil==='loja'?(m.remetente_nome||'Loja')
    :m.remetente_perfil==='entregador'?(m.remetente_nome||'Entregador')
    :(m.remetente_nome||(m.remetente_perfil==='suporte'?'Suporte':'Admin'));
  const textoEscapado=(m.texto||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  return`<div style="align-self:${minhaMsg?'flex-end':'flex-start'};max-width:75%;display:flex;flex-direction:column">
    ${!minhaMsg?`<div style="font-size:10px;color:var(--text3);margin-bottom:2px;padding:0 4px">${nomeExibido}</div>`:''}
    <div style="background:${minhaMsg?'var(--accent)':'var(--surface)'};color:${minhaMsg?'#fff':'var(--text)'};border:1px solid ${minhaMsg?'transparent':'var(--border)'};border-radius:12px;padding:8px 12px;font-size:13px;white-space:pre-wrap;word-break:break-word">${textoEscapado}</div>
    <div style="font-size:10px;color:var(--text3);margin-top:2px;padding:0 4px;text-align:${minhaMsg?'right':'left'}">${formatarHora(m.created_at)}</div>
  </div>`;
}
function _renderMensagensChat(){
  const el=document.getElementById('chat-loja-mensagens')||document.getElementById('chat-admin-mensagens');
  if(!el)return;
  if(!_chatMensagensCache.length){el.innerHTML='<div style="text-align:center;color:var(--text3);font-size:13px;margin-top:20px">Nenhuma Mensagem Ainda. Envie A Primeira!</div>';return;}
  el.innerHTML=_chatMensagensCache.map(_bolhaChatHtml).join('');
  el.scrollTop=el.scrollHeight;
}
// Busca a conversa inteira (loja OU entregador — _chatLojaAtual e
// _chatEntregadorAtual são mutuamente exclusivos), renderiza, e marca como
// lida o lado oposto ao perfil de quem está vendo agora (o participante lê
// o que adm/suporte escreveram, e vice-versa — adm e suporte compartilham
// o mesmo "lado" da conversa, então uma mensagem do participante fica lida
// assim que QUALQUER um dos dois abrir, não precisa dos dois abrirem
// separado). Generalizado (achado real na auditoria): a versão antiga
// comparava só contra 'loja' — pra uma conversa de entregador vista pelo
// admin, isso nunca batia (remetente_perfil nunca é 'loja' ali), e a
// mensagem do entregador nunca era marcada como lida.
async function _carregarMensagensChat(){
  const filtro=_chatLojaAtual?`loja_id=eq.${_chatLojaAtual}`:_chatEntregadorAtual?`entregador_id=eq.${_chatEntregadorAtual}`:null;
  if(!filtro)return;
  const rows=await db('mensagens_chat','GET',null,`?${filtro}&order=created_at.asc`).catch(()=>[]);
  _chatMensagensCache=Array.isArray(rows)?rows:[];
  _renderMensagensChat();
  const souLoja=currentPerfil==='loja';
  const perfilContraparte=_chatLojaAtual?'loja':'entregador';
  const idsNaoLidas=_chatMensagensCache.filter(m=>(souLoja?m.remetente_perfil!==perfilContraparte:m.remetente_perfil===perfilContraparte)&&!m.lida).map(m=>m.id);
  if(idsNaoLidas.length){
    await dbPatch('mensagens_chat',{lida:true},`?id=in.(${idsNaoLidas.join(',')})`);
    if(souLoja)_carregarBadgeChatLoja();
  }
}
async function _enviarMensagemChat(){
  const input=document.getElementById('chat-loja-input')||document.getElementById('chat-admin-input');
  const texto=(input?.value||'').trim();
  if(!texto||(!_chatLojaAtual&&!_chatEntregadorAtual))return;
  input.value='';
  const payload={remetente_perfil:currentPerfil,remetente_usuario_id:currentUser?.id||null,remetente_nome:currentUser?.nome||null,texto,lida:false};
  if(_chatLojaAtual)payload.loja_id=_chatLojaAtual;else payload.entregador_id=_chatEntregadorAtual;
  const res=await db('mensagens_chat','POST',payload);
  if(!res||res.length===0){showNotif('❌ Erro Ao Enviar','Não Foi Possível Enviar A Mensagem','var(--red)');input.value=texto;return;}
  await _carregarMensagensChat();
  if(currentPerfil!=='loja')await _carregarListaConversasAdmin();
}

// ── Loja: modal com a conversa única dela ──
function _abrirChatLoja(){
  if(!currentUser?.loja_id)return;
  let modal=document.getElementById('modal-chat-loja');
  if(!modal){modal=document.createElement('div');modal.id='modal-chat-loja';modal.className='modal-overlay';document.body.appendChild(modal);}
  modal.innerHTML=`<div class="modal" style="max-width:480px;height:70vh;display:flex;flex-direction:column">
    <div class="modal-header"><span class="modal-title">${_icone('message-circle',18)} Chat Com O Suporte</span><button class="modal-close" onclick="_fecharChatLoja()">${_icone('x',16)}</button></div>
    <div id="chat-loja-mensagens" style="flex:1;overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:10px;background:var(--surface2)"><div style="text-align:center;color:var(--text3);font-size:13px">Carregando...</div></div>
    <div style="padding:12px 16px;border-top:1px solid var(--border);display:flex;gap:8px;flex-shrink:0">
      <input id="chat-loja-input" placeholder="Digite Sua Mensagem..." onkeydown="if(event.key==='Enter')_enviarMensagemChat()" style="flex:1;background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:9px 12px;color:var(--text);font-family:Inter,sans-serif;font-size:13px;outline:none"/>
      <button onclick="_enviarMensagemChat()" style="background:var(--accent);color:#fff;border:none;border-radius:8px;padding:9px 16px;font-size:13px;font-weight:700;cursor:pointer;font-family:Inter,sans-serif">Enviar</button>
    </div>
  </div>`;
  modal.classList.add('open');
  modal.onclick=e=>{if(e.target===modal)_fecharChatLoja();};
  _chatLojaAtual=currentUser.loja_id;_chatEntregadorAtual=null;
  _carregarMensagensChat();
  clearInterval(_chatPollInterval);
  _chatPollInterval=setInterval(_carregarMensagensChat,10000);
}
function _fecharChatLoja(){
  document.getElementById('modal-chat-loja')?.classList.remove('open');
  clearInterval(_chatPollInterval);_chatPollInterval=null;
}

// ── Admin/Suporte: inbox com lista de lojas + conversa selecionada ──
// Modal (não mais página de menu) — mesmo ponto de entrada (botão flutuante
// 💬 no mapa) que a loja usa, só que aqui abre a lista em vez de ir direto
// pra uma conversa, já que o admin/suporte tem várias lojas conversando.
async function _abrirChatAdmin(){
  let modal=document.getElementById('modal-chat-admin');
  if(!modal){modal=document.createElement('div');modal.id='modal-chat-admin';modal.className='modal-overlay';document.body.appendChild(modal);}
  modal.innerHTML=`<div class="modal" style="max-width:820px;width:92vw;height:75vh;display:flex;flex-direction:column;padding:0;overflow:hidden">
    <div class="modal-header" style="padding:14px 20px;flex-shrink:0"><span class="modal-title">${_icone('message-circle',18)} Chat</span><button class="modal-close" onclick="_fecharChatAdmin()">${_icone('x',16)}</button></div>
    <div class="chat-admin-layout" style="flex:1;display:flex;gap:14px;min-height:0;padding:0 16px 16px">
      <div style="width:260px;flex-shrink:0;overflow-y:auto;border:1px solid var(--border);border-radius:10px" id="chat-lista-conversas"><div style="padding:24px;text-align:center;color:var(--text3)">Carregando...</div></div>
      <div style="flex:1;display:flex;flex-direction:column;min-width:0;border:1px solid var(--border);border-radius:10px;overflow:hidden" id="chat-painel-conversa">
        <div style="flex:1;display:flex;align-items:center;justify-content:center;color:var(--text3);font-size:13px">Selecione Uma Conversa</div>
      </div>
    </div>
  </div>`;
  modal.classList.add('open');
  modal.onclick=e=>{if(e.target===modal)_fecharChatAdmin();};
  _chatLojaAtual=null;_chatEntregadorAtual=null;
  clearInterval(_chatPollInterval);
  await _carregarListaConversasAdmin();
  _chatPollInterval=setInterval(_carregarListaConversasAdmin,10000);
}
function _fecharChatAdmin(){
  document.getElementById('modal-chat-admin')?.classList.remove('open');
  clearInterval(_chatPollInterval);_chatPollInterval=null;
}
// Lista única, misturada (loja + entregador), ordenada por mensagem mais
// recente — mesmo padrão visual/estrutural de antes (só loja), decisão
// técnica de manter consistência em vez de criar abas (chat Parceiro
// Let's Go, 2026-09-08). Cada conversa é identificada por
// "loja:<id>"/"ent:<id>" (nunca colide, tipos diferentes de UUID) —
// evita juntar por engano uma loja e um entregador com o mesmo id.
async function _carregarListaConversasAdmin(){
  const el=document.getElementById('chat-lista-conversas');if(!el)return;
  const rows=await db('mensagens_chat','GET',null,'?select=*,lojas(nome),entregadores(nome)&order=created_at.desc').catch(()=>[]);
  const porConversa=new Map();
  (Array.isArray(rows)?rows:[]).forEach(m=>{
    const tipo=m.loja_id?'loja':'entregador';
    const idParticipante=m.loja_id||m.entregador_id;
    const chave=`${tipo}:${idParticipante}`;
    if(!porConversa.has(chave))porConversa.set(chave,{
      tipo,id:idParticipante,
      nome:tipo==='loja'?(m.lojas?.nome||'—'):(m.entregadores?.nome||'—'),
      ultima:m,naoLidas:0,urgente:false,
    });
    const c=porConversa.get(chave);
    if(m.remetente_perfil===tipo&&!m.lida){
      c.naoLidas++;
      // Item 5: "Preciso sair do pedido" precisa de resposta rápida
      // (motoboy travado, precisa de realocação) — destaca a conversa
      // inteira enquanto essa mensagem específica continuar não lida.
      if(tipo==='entregador'&&m.motivo===MOTIVO_SAIR_PEDIDO)c.urgente=true;
    }
  });
  _chatConversasCache=[...porConversa.values()].sort((a,b)=>new Date(b.ultima.created_at)-new Date(a.ultima.created_at));
  _chatNaoLidasAdminCount=_chatConversasCache.reduce((s,c)=>s+c.naoLidas,0);
  renderNavSidebar(_navAtivo);
  if(!_chatConversasCache.length){el.innerHTML='<div style="padding:24px;text-align:center;color:var(--text3);font-size:13px">Nenhuma Conversa Ainda</div>';return;}
  el.innerHTML=_chatConversasCache.map(c=>{
    const selecionada=(c.tipo==='loja'?_chatLojaAtual===c.id:_chatEntregadorAtual===c.id);
    return`<div onclick="_abrirConversaAdmin('${c.tipo}','${c.id}')" style="padding:12px 14px;border-bottom:1px solid var(--border);cursor:pointer;background:${selecionada?'var(--surface2)':'transparent'};${c.urgente?'border-left:3px solid #ef4444':''}">
    <div style="display:flex;justify-content:space-between;align-items:center;gap:6px">
      <span style="font-weight:600;font-size:13px;color:var(--text)">${c.tipo==='loja'?'🏪':'🛵'} ${c.nome}</span>
      ${c.naoLidas>0?`<span style="background:${c.urgente?'#ef4444':'var(--accent)'};color:#fff;border-radius:10px;min-width:18px;height:18px;font-size:10px;font-weight:700;display:flex;align-items:center;justify-content:center;padding:0 4px;flex-shrink:0">${c.naoLidas}</span>`:''}
    </div>
    ${c.urgente?`<div style="font-size:10px;color:#ef4444;font-weight:700;margin-top:3px">🚨 Quer Sair Do Pedido — Responder Rápido</div>`:''}
    <div style="font-size:11px;color:var(--text3);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${(c.ultima.texto||'').substring(0,60)}</div>
  </div>`;
  }).join('');
  if((_chatLojaAtual||_chatEntregadorAtual)&&document.getElementById('chat-admin-mensagens'))_carregarMensagensChat();
}
function _abrirConversaAdmin(tipo,id){
  if(tipo==='loja'){_chatLojaAtual=id;_chatEntregadorAtual=null;}
  else{_chatEntregadorAtual=id;_chatLojaAtual=null;}
  const conversa=_chatConversasCache.find(c=>c.tipo===tipo&&c.id===id);
  const painel=document.getElementById('chat-painel-conversa');
  if(!painel)return;
  painel.innerHTML=`
    <div style="padding:14px 16px;border-bottom:1px solid var(--border);font-weight:700;color:var(--text);flex-shrink:0">${tipo==='loja'?'🏪':'🛵'} ${conversa?.nome||''}</div>
    <div id="chat-admin-mensagens" style="flex:1;overflow-y:auto;padding:16px;display:flex;flex-direction:column;gap:10px;background:var(--surface2)"><div style="text-align:center;color:var(--text3);font-size:13px">Carregando...</div></div>
    <div style="padding:12px 16px;border-top:1px solid var(--border);display:flex;gap:8px;flex-shrink:0">
      <input id="chat-admin-input" placeholder="Digite Sua Mensagem..." onkeydown="if(event.key==='Enter')_enviarMensagemChat()" style="flex:1;background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:9px 12px;color:var(--text);font-family:Inter,sans-serif;font-size:13px;outline:none"/>
      <button onclick="_enviarMensagemChat()" style="background:var(--accent);color:#fff;border:none;border-radius:8px;padding:9px 16px;font-size:13px;font-weight:700;cursor:pointer;font-family:Inter,sans-serif">Enviar</button>
    </div>`;
  _carregarMensagensChat();
  // Só pra tirar o destaque/badge da linha selecionada na lista à esquerda
  // (recarrega a lista inteira — simples, sem duplicar a lógica de
  // agregação em outro lugar só pra atualizar uma linha).
  _carregarListaConversasAdmin();
}

// ── PULL-TO-REFRESH (gesto touch, estilo app nativo) ──
// Puro touchstart/touchmove/touchend — nunca disparam com mouse, então já
// "só ativa em touch" sem precisar de detecção de user-agent nenhuma.
// O gesto só arma se o toque começar perto do topo da tela (~100px): esse
// layout mistura vários containers com scroll próprio (tabela do mapa,
// sidebar de pedidos, listagens internas) em vez de ser uma página inteira
// rolável — checar "scrollTop de um container específico" seria diferente
// pra cada tela; iniciar perto do topo é a forma simples e segura de não
// capturar por engano um scroll dentro de uma dessas listas internas.
// Sem indicador visual de propósito (removido a pedido — ficava sobreposto
// feio em cima dos contadores do mapa) e sem refresh parcial por tela:
// dispara um reload completo da página, igual um hard refresh de
// navegador, ignorando cache (navega pra uma URL com cache-buster em vez
// de usar location.reload(), já que o parâmetro forceGet de reload() foi
// descontinuado e não tem mais efeito nos navegadores atuais).
let _pullStartY=null,_pullDistancia=0,_pullAtivo=false,_pullRefreshing=false;
const _PULL_LIMIAR=70;
function _pullToRefreshExecutar(){
  if(_pullRefreshing)return;
  _pullRefreshing=true;
  const url=new URL(location.href);
  url.searchParams.set('_pr',Date.now());
  location.href=url.toString();
}
function _iniciarPullToRefresh(){
  document.addEventListener('touchstart',(e)=>{
    if(_pullRefreshing||!currentPerfil){_pullAtivo=false;return;}
    if(e.touches[0].clientY>100){_pullAtivo=false;return;}
    _pullStartY=e.touches[0].clientY;
    _pullAtivo=true;_pullDistancia=0;
  },{passive:true});
  document.addEventListener('touchmove',(e)=>{
    if(!_pullAtivo||_pullStartY===null)return;
    const dy=e.touches[0].clientY-_pullStartY;
    _pullDistancia=dy<=0?0:dy;
  },{passive:true});
  document.addEventListener('touchend',()=>{
    if(!_pullAtivo)return;
    _pullAtivo=false;
    if(_pullDistancia>=_PULL_LIMIAR)_pullToRefreshExecutar();
    _pullStartY=null;_pullDistancia=0;
  },{passive:true});
}
_iniciarPullToRefresh();

// Relógio ao vivo no topbar (#topbar-relogio, index.html) — conferência
// visual permanente pro operador: se o painel algum dia voltar a divergir
// do horário real (ver bug de fuso que já corrigimos), fica óbvio comparando
// com um relógio físico. timeZone fixo em 'America/Sao_Paulo' — não usa o
// fuso local do navegador, pra alguém acessando de fora do Brasil não ver
// hora errada.
function _atualizarRelogioTopbar(){
  const el=document.getElementById('topbar-relogio');
  if(!el)return;
  const agora=new Date();
  const data=agora.toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'});
  const hora=agora.toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',second:'2-digit'});
  el.textContent=`${data} ${hora}`;
  // Hooks da Visão Executiva (CEO) — reaproveita este mesmo tick de 1s em vez
  // de criar um segundo interval; vira no-op (getElementById null) em
  // qualquer outra página.
  const ceoData=document.getElementById('ceo-data-atual');if(ceoData)ceoData.textContent=data;
  const ceoHora=document.getElementById('ceo-hora-atual');if(ceoHora)ceoHora.textContent=hora.slice(0,5);
  const ceoAt=document.getElementById('ceo-atualizado-ha');
  if(ceoAt&&_ceoUltimaAtualizacao){
    const min=Math.floor((Date.now()-_ceoUltimaAtualizacao)/60000);
    ceoAt.textContent=min<1?'Atualizado Agora Mesmo':`Atualizado Há ${min} min`;
  }
}
_atualizarRelogioTopbar();
setInterval(_atualizarRelogioTopbar,1000);
const _agendadoInputBrasilia=(dataStr)=>{if(!dataStr)return'';return new Date(dataStr).toLocaleString('sv-SE',{timeZone:'America/Sao_Paulo'}).replace(' ','T').slice(0,16);};
const _defaultAgendadoBrasilia=(minutos=30)=>new Date(Date.now()+minutos*60000).toLocaleString('sv-SE',{timeZone:'America/Sao_Paulo'}).replace(' ','T').slice(0,16);
// Bug real corrigido 2026-09-14 (pedidos #7448/#3077, SENSUS BISTRÔ):
// nada validava que o valor digitado/escolhido no datetime-local de
// agendamento estivesse no futuro — os dois só checavam "campo
// preenchido", não "data válida". O scheduler (_runScheduler) libera
// qualquer agendado com agendado_para<=agora na primeira checagem, então
// um agendamento "nascido vencido" vira pronto (e despacha motoboy) em
// segundos, sem ninguém perceber que a data estava errada. Usada nos dois
// pontos que gravam agendado_para (criarPedido/salvarEdicaoPedido).
const _agendamentoNoFuturo=(agendadoParaVal)=>!agendadoParaVal||new Date(agendadoParaVal).getTime()>Date.now();


