// Autorização real por usuário (RLS depende disso) — antes disso, db()/dbPatch()
// sempre mandavam a chave anon estática, então toda policy de RLS via
// auth.uid()/current_perfil() enxergava um request anônimo, não o usuário
// logado. Renova o access_token proativamente se estiver perto de expirar
// (refresh_token já salvo no login); se não houver sessão válida nem
// refresh possível, cai pra SB_KEY — que hoje em diante é tratado pelas
// policies como anônimo de verdade (sem allow-all), não como bypass.
async function _authHeader(tokenOverride){
  // tokenOverride: usado só pela checagem de usuarios_painel dentro do
  // próprio fazerLogin() — nesse momento o access_token novo ainda não foi
  // salvo em sessionStorage (só é salvo depois que essa checagem passa),
  // então ler do sessionStorage aqui pegaria a sessão antiga/vazia e a
  // policy self_or_admin bloquearia a checagem de um login válido.
  if(tokenOverride)return `Bearer ${tokenOverride}`;
  let sessao=null;
  try{sessao=JSON.parse(sessionStorage.getItem('lg_session')||'null');}catch{}
  if(!sessao?.access_token)return `Bearer ${SB_KEY}`;

  const expiraEm=(sessao.expires_at||0)*1000-Date.now();
  if(expiraEm<60000 && sessao.refresh_token){
    try{
      const r=await fetch(`${SB_URL}/auth/v1/token?grant_type=refresh_token`,{
        method:'POST',
        headers:{'apikey':SB_KEY,'Content-Type':'application/json'},
        body:JSON.stringify({refresh_token:sessao.refresh_token}),
      });
      if(r.ok){
        const nova=await r.json();
        sessao={access_token:nova.access_token,refresh_token:nova.refresh_token,expires_at:nova.expires_at};
        sessionStorage.setItem('lg_session',JSON.stringify(sessao));
      }
    }catch(e){console.error('[auth] falha ao renovar token:',e);}
  }
  return `Bearer ${sessao.access_token}`;
}

async function db(table,method='GET',body=null,filters='',tokenOverride){
  const url=`${SB_URL}/rest/v1/${table}${filters}`;
  const h={'apikey':SB_KEY,'Authorization':await _authHeader(tokenOverride),'Content-Type':'application/json'};
  if(method==='POST'||method==='PATCH')h['Prefer']='return=representation';
  try{
    const r=await fetch(url,{method,headers:h,body:body?JSON.stringify(body):null});
    if(!r.ok){
      const errBody=await r.text().catch(()=>'');
      console.error(`[db] ERRO ${r.status} ${r.statusText} | ${method} ${url}`,errBody);
      return[];
    }
    const t=await r.text();
    return t?JSON.parse(t):[];
  }catch(e){
    console.error(`[db] EXCEPTION | ${method} ${url}`,e);
    return[];
  }
}

// Chama uma função RPC do Postgres (POST /rest/v1/rpc/<fn>) — usada quando a
// agregação precisa rodar no banco (GROUP BY/COUNT) em vez de trazer linhas
// pro client, que fica sujeito ao limite de linhas do PostgREST (ver bug do
// Relatório de Entregas, app.js:_buscarPedidosAdmin).
async function dbRpc(fnName,args={}){
  const url=`${SB_URL}/rest/v1/rpc/${fnName}`;
  const h={'apikey':SB_KEY,'Authorization':await _authHeader(),'Content-Type':'application/json'};
  try{
    const r=await fetch(url,{method:'POST',headers:h,body:JSON.stringify(args)});
    if(!r.ok){
      const errBody=await r.text().catch(()=>'');
      console.error(`[dbRpc] ERRO ${r.status} ${r.statusText} | ${fnName}`,errBody);
      return[];
    }
    const t=await r.text();
    return t?JSON.parse(t):[];
  }catch(e){
    console.error(`[dbRpc] EXCEPTION | ${fnName}`,e);
    return[];
  }
}

// Busca TODAS as linhas de uma tabela pra um filtro, sem limite implícito —
// pagina em blocos de `pageSize` via offset/limit até uma página vir com
// menos linhas que pageSize (sinal de que acabou). Usar quando o valor de
// cada linha depende de lógica de negócio no client (ex: tabela de preço
// por faixa de KM em verFaturaCobranca) que não compensa duplicar em SQL —
// se o cálculo puder virar agregação pura (COUNT/SUM), prefira dbRpc.
// filtroBase não pode conter `limit=`/`offset=` (essa função controla os
// dois) e precisa ter um `order=` determinístico, senão a paginação pode
// pular ou repetir linha entre páginas.
async function _dbTodasLinhas(table,filtroBase,pageSize=500){
  let offset=0,todas=[],pagina;
  do{
    pagina=await db(table,'GET',null,`${filtroBase}&limit=${pageSize}&offset=${offset}`);
    if(!Array.isArray(pagina))break;
    todas=todas.concat(pagina);
    offset+=pageSize;
  }while(pagina.length===pageSize);
  return todas;
}

async function dbPatch(table,body,filter,tokenOverride){
  const url=`${SB_URL}/rest/v1/${table}${filter}`;
  const h={'apikey':SB_KEY,'Authorization':await _authHeader(tokenOverride),'Content-Type':'application/json','Prefer':'return=representation'};
  try{
    const r=await fetch(url,{method:'PATCH',headers:h,body:JSON.stringify(body)});
    if(!r.ok){const msg=await r.text();console.error(`PATCH ${table} ${r.status}:`,msg);return null;}
    const t=await r.text();return t?JSON.parse(t):[];
  }catch(e){console.error(`PATCH ${table} exception:`,e);return null;}
}

async function _criarContaAuth(email,senha){
  try{
    const r=await fetch(`${SB_URL}/auth/v1/signup`,{method:'POST',headers:{'apikey':SB_KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password:senha})});
    const data=await r.json();
    if(!r.ok||!data.user?.id)return{ok:false,error:data.error_description||data.msg||'Verifique O E-mail.'};
    return{ok:true,userId:data.user.id};
  }catch{return{ok:false,error:'Erro De Conexão.'};}
}

// Redefine a senha de uma conta direto no Supabase Auth (Admin API, via
// admin-reset-senha), sem disparar e-mail nem expor link/host — usado nas
// telas de Editar Entregador/Usuário/Loja. Requer o access_token real de
// quem está logado (a Edge Function confere que é um admin ativo).
function _toggleSenhaVisivel(inputId,btn){
  const el=document.getElementById(inputId);if(!el)return;
  if(el.type==='password'){el.type='text';btn.innerHTML=_icone('eye-off',16);}else{el.type='password';btn.innerHTML=_icone('eye',16);}
}
async function _redefinirSenhaAuth(email,novaSenha){
  let sessao=null;
  try{sessao=JSON.parse(sessionStorage.getItem('lg_session')||'null');}catch{}
  if(!sessao?.access_token)return{ok:false,error:'Sessão Expirada — Faça Login Novamente.'};
  try{
    const r=await fetch(`${SB_URL}/functions/v1/admin-reset-senha`,{
      method:'POST',
      headers:{'Content-Type':'application/json','Authorization':`Bearer ${sessao.access_token}`},
      body:JSON.stringify({email,novaSenha})
    });
    const data=await r.json().catch(()=>({}));
    if(!r.ok)return{ok:false,error:data.error||`Erro ${r.status}`};
    return{ok:true};
  }catch{return{ok:false,error:'Erro De Conexão.'};}
}

async function logAcao(acao,detalhes={}){
  if(!currentUser)return;
  await db('logs_acoes','POST',{usuario_id:currentUser.id,acao,detalhes});
}

function tocarSomPronto(){
  try{
    const ctx=new(window.AudioContext||window.webkitAudioContext)();
    [[880,.0],[1100,.18],[880,.36],[1100,.54]].forEach(([freq,delay])=>{
      const osc=ctx.createOscillator(),gain=ctx.createGain();
      osc.connect(gain);gain.connect(ctx.destination);
      osc.frequency.value=freq;osc.type='sine';
      gain.gain.setValueAtTime(.35,ctx.currentTime+delay);
      gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+delay+.18);
      osc.start(ctx.currentTime+delay);osc.stop(ctx.currentTime+delay+.2);
    });
  }catch(e){}
}

async function _aplicarPrecoDinamico(p){
  const pdC=_getPdCliente(p.loja_id);
  const pdE=_getPdEntregador(p.loja_id);
  if(pdC<=0&&pdE<=0)return;
  // Bug real corrigido (2026-09-22, achado real via Auditoria): as duas
  // linhas abaixo chamavam _calcTaxaLoja/_calcTaxaMotoboy sem 2º argumento,
  // então caíam sempre na tabela GLOBAL padrão (_faixasCobranca/_faixasPagamento),
  // ignorando a tabela de preço PRÓPRIA da loja (tabela_cobranca_id/
  // tabela_pagamento_id) quando ela tem contrato customizado. Como essa
  // função roda toda vez que um pedido vira "pronto" (praticamente todo
  // pedido, via processarAutoPronto ou o botão rápido), isso sobrescrevia
  // silenciosamente o taxa_entrega correto pelo valor da tabela padrão
  // sempre que o Preço Dinâmico estava ativo — confirmado em produção,
  // 18 pedidos reais nos últimos 30 dias cobrados a mais de lojas com
  // tabela própria (ex: NOVIGO CARNES, COMAMOR VEGETAL — "CONTRATO FIXO
  // 100% DEMANDA"). Busca a tabela real da loja antes de recalcular.
  const [faixasCob,faixasPag]=await Promise.all([_getFaixasCobranca(p.loja_id),_getFaixasPagamento(p.loja_id)]);
  const merged={...p,preco_dinamico:pdC};
  const taxa_entrega=_calcTaxaLoja(merged,faixasCob.length?faixasCob:undefined);
  const mergedE={...p,preco_dinamico:pdE};
  const taxa_entrega_motoboy=_calcTaxaMotoboy(mergedE,faixasPag.length?faixasPag:undefined);
  const patch={preco_dinamico:pdC,taxa_entrega,updated_at:_agoraBrasilia()};
  if(pdE>0)patch.taxa_entrega_motoboy=taxa_entrega_motoboy;
  await db('pedidos','PATCH',patch,`?id=eq.${p.id}`);
  Object.assign(p,patch);
}

async function processarAutoPronto(){
  const agora=new Date();
  const pedidosRecebidos=allPedidos.filter(p=>(p.status_detalhado==='recebido'||p.status==='recebido')&&!_pedidoStatusLock.has(p.id));
  for(const p of pedidosRecebidos){
    const base=p.recebido_em||p.created_at;if(!base)continue;
    const diff=(agora-new Date(base))/1000;
    if(diff>=60){
      const codigo=String(Math.floor(Math.random()*9000)+1000);
      const res=await db('pedidos','PATCH',{status:'pronto',status_detalhado:'pronto',pronto_em:_agoraBrasilia(),codigo_confirmacao:codigo,updated_at:_agoraBrasilia()},`?id=eq.${p.id}`);
      if(res&&(Array.isArray(res)?res.length>0:res.id)){
        _pedidoStatusLock.set(p.id,{status:'pronto',status_detalhado:'pronto',expires:Infinity});
        p.status='pronto';p.status_detalhado='pronto';
        await _aplicarPrecoDinamico(p);
      }
    }
  }
}

async function processarPontosAutomaticos(){
  // Progressão por tempo sem alocação, a partir de pronto_em (mesmo marco do
  // SLA) — não created_at. Substitui (não soma) o valor base conforme a
  // faixa. O congelamento no momento do aceite é feito por trigger no banco
  // (migrations/add_pontos_progressivos.sql), então aqui só mexemos em
  // pedidos ainda sem motoboy/entregador alocado.
  const agora=Date.now();
  const prontos=allPedidos.filter(p=>(p.status_detalhado==='pronto'||p.status==='pronto')&&p.pronto_em&&!p.motoboy_id&&!p.entregador_id);
  for(const p of prontos){
    const base=p.pontos_base??p.pontos??4;
    const minutos=(agora-_parseUtc(p.pronto_em).getTime())/60000;
    let novosPontos;
    if(minutos<10)novosPontos=base;
    else if(minutos<20)novosPontos=base+150;
    else if(minutos<30)novosPontos=base+300;
    else novosPontos=base+700;
    if((p.pontos??base)!==novosPontos){
      await db('pedidos','PATCH',{pontos:novosPontos,updated_at:_agoraBrasilia()},`?id=eq.${p.id}`);
      const el=document.getElementById(`pontos-${p.id}`);if(el)el.textContent=novosPontos;
      p.pontos=novosPontos;
    }
  }
}

function verificarNovosProtos(pedidos){
  pedidos.forEach(p=>{
    if((p.status_detalhado==='pronto'||p.status==='pronto')&&!idsProntoNotificados.has(p.id)){
      idsProntoNotificados.add(p.id);tocarSomPronto();
      showNotif('🔔 Pedido Pronto!',`#${p.numero||p.id?.substring(0,6)} aguardando motoboy`,'var(--pink)');
    }
    if(p.status==='finalizado'||p.status==='entregue')idsProntoNotificados.delete(p.id);
  });
}

// Emoji no começo do título de notificação → ícone Lucide com o mesmo
// sentido; os de status (✅ ❌ ⚠️ ℹ️) caem no ícone do tipo pela cor.
const _NOTIF_ICONE_EMOJI={'✅':'circle-check','❌':'circle-x','⚠':'triangle-alert','ℹ':'info','🗑':'trash-2','🔔':'bell','⏰':'alarm-clock','🔒':'lock','⏳':'hourglass','📲':'send'};
function showNotif(title,msg,color='var(--green)'){
  const _c=color||'';
  let type='info';
  if(_c.includes('green')||_c.includes('22c55e'))type='success';
  else if(_c.includes('red')||_c.includes('ef4444'))type='error';
  else if(_c.includes('yellow')||_c.includes('eab308')||_c.includes('f59e0b')||_c.includes('orange')||_c.includes('f97316'))type='warning';
  const _cf={
    success:{bg:'#0a1e10',bc:'#22c55e',ic:'#22c55e',tc:'#4ade80',icone:'circle-check'},
    error:  {bg:'#1e0a0a',bc:'#ef4444',ic:'#ef4444',tc:'#f87171',icone:'circle-x'},
    warning:{bg:'#1e180a',bc:'#eab308',ic:'#d97706',tc:'#fbbf24',icone:'triangle-alert'},
    info:   {bg:'#0a0f1e',bc:'#1A56DB',ic:'#60a5fa',tc:'#60a5fa',icone:'info'},
  };
  const cf=_cf[type];
  // Fase 4 Lucide (2026-09-29): o emoji do começo do título (✅ ❌ ⚠️ 🗑️...)
  // sai do texto e vira ícone Lucide na cor do TIPO (verde sucesso,
  // vermelho erro, amarelo aviso, azul info). Emoji com significado próprio
  // (lixeira, sino, cadeado...) escolhe o desenho; sem emoji, usa o ícone
  // do tipo — toda notificação fica com ícone. Feito aqui (central) e não
  // em cada chamada: cobre também títulos montados dinamicamente.
  let _titulo=String(title??'');let _icNome=cf.icone;
  const _mEmo=_titulo.match(/^\s*((?:\p{Extended_Pictographic}|\p{Regional_Indicator})\uFE0F?)\s*/u);
  if(_mEmo){_icNome=_NOTIF_ICONE_EMOJI[_mEmo[1].replace('\uFE0F','')]||cf.icone;_titulo=_titulo.slice(_mEmo[0].length);}
  const id='_t'+Date.now()+Math.random().toString(36).slice(2,5);
  let stack=document.getElementById('_toast_stack');
  if(!stack){
    stack=document.createElement('div');
    stack.id='_toast_stack';
    stack.style.cssText='position:fixed;bottom:30px;right:24px;z-index:9999;display:flex;flex-direction:column-reverse;gap:10px;align-items:flex-end;pointer-events:none';
    document.body.appendChild(stack);
  }
  const toast=document.createElement('div');
  toast.id=id;
  toast.style.cssText=`pointer-events:all;min-width:320px;max-width:420px;padding:14px 18px;background:${cf.bg};border:1px solid ${cf.bc}33;border-left:4px solid ${cf.bc};border-radius:12px;display:flex;gap:14px;align-items:flex-start;box-shadow:0 8px 32px rgba(0,0,0,.65);transform:translateX(calc(100% + 32px));opacity:0;transition:transform .35s cubic-bezier(.16,1,.3,1),opacity .25s ease;font-family:Inter,sans-serif`;
  toast.innerHTML=`<img src="https://letsgodeliverybr.github.io/painel/img/logo.png" alt="Let's Go" style="flex-shrink:0;width:40px;height:40px;object-fit:contain;border-radius:8px" onerror="this.style.display='none'"/><div style="flex:1;min-width:0;overflow:hidden"><div style="display:flex;align-items:center;gap:4px;margin-bottom:4px"><span style="font-size:14px;font-weight:600;color:${cf.tc};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">Let's Go Delivery</span></div><div style="font-size:13px;font-weight:600;color:${cf.tc};margin-bottom:${msg?'3px':'0'};display:flex;align-items:flex-start;gap:6px"><span style="color:${cf.ic};display:inline-flex;flex-shrink:0;margin-top:1px">${_icone(_icNome,16)}</span><span style="min-width:0">${_titulo}</span></div>${msg?`<div style="font-size:12px;color:${cf.tc};opacity:.75;line-height:1.4;word-break:break-word">${msg}</div>`:''}</div><button id="${id}_x" style="flex-shrink:0;background:none;border:none;cursor:pointer;padding:2px;color:#64748b;line-height:1;align-self:flex-start"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>`;
  stack.appendChild(toast);
  const dismiss=()=>{toast.style.opacity='0';toast.style.transform='translateX(calc(100% + 32px))';setTimeout(()=>toast.remove(),350);};
  document.getElementById(id+'_x').addEventListener('click',dismiss);
  let _dt=setTimeout(dismiss,4000);
  toast.addEventListener('mouseenter',()=>clearTimeout(_dt));
  toast.addEventListener('mouseleave',()=>{_dt=setTimeout(dismiss,2000);});
  requestAnimationFrame(()=>requestAnimationFrame(()=>{toast.style.transform='translateX(0)';toast.style.opacity='1';}));
}

