function _scTrocarAba(aba){
  _scSubAba=aba;
  ['lojas','entregadores'].forEach(id=>{
    const b=document.getElementById(`sc-btn-${id}`);if(!b)return;
    const a=_scSubAba===id;
    b.style.borderBottom=`2px solid ${a?'var(--accent)':'transparent'}`;
    b.style.color=a?'var(--accent)':'var(--text3)';
  });
  document.getElementById('sc-f-nome').value='';
  _scBuscar();
}

async function _scBuscar(){
  const wrap=document.getElementById('sc-tabela');if(!wrap)return;
  wrap.innerHTML='<div style="padding:24px;text-align:center;color:var(--text3)">Buscando...</div>';
  const isLojas=_scSubAba==='lojas';
  const tabela=isLojas?'creditos_lojas':'creditos_entregadores';
  const joinField=isLojas?'lojas':'entregadores';
  const nome=(document.getElementById('sc-f-nome')?.value||'').toLowerCase();
  const ini=document.getElementById('sc-f-ini')?.value;
  const fim=document.getElementById('sc-f-fim')?.value;
  const tipo=document.getElementById('sc-f-tipo')?.value;
  let qs=`?select=*,${joinField}(nome)&order=created_at.desc&limit=500`;
  if(ini)qs+=`&created_at=gte.${_inicioDiaBrasilia(ini)}`;
  if(fim)qs+=`&created_at=lte.${_fimDiaBrasilia(fim)}`;
  if(tipo==='credito')qs+='&tipo=eq.credito';
  else if(tipo==='debito')qs+='&tipo=eq.debito';
  else if(tipo==='bonus')qs+='&tipo=eq.bonus';
  const rows=await db(tabela,'GET',null,qs);
  const data=(Array.isArray(rows)?rows:[])
    .filter(r=>!nome||(r[joinField]?.nome||'').toLowerCase().includes(nome))
    .filter(r=>{const obs=(r.observacoes||'').toLowerCase();return!obs.startsWith('entrega #')&&!obs.startsWith('estorno #');});
  const totC=data.filter(r=>r.tipo==='credito').reduce((s,r)=>s+(parseFloat(r.valor)||0),0);
  const totD=data.filter(r=>r.tipo==='debito').reduce((s,r)=>s+(parseFloat(r.valor)||0),0);
  const totB=data.filter(r=>r.tipo==='bonus').reduce((s,r)=>s+(parseFloat(r.valor)||0),0);
  const saldo=totC+totB-totD;
  const e1=document.getElementById('sc-tot-c'),e2=document.getElementById('sc-tot-d'),e3=document.getElementById('sc-tot-s'),e4=document.getElementById('sc-tot-b');
  if(e1)e1.textContent=`R$ ${totC.toFixed(2)}`;
  if(e2)e2.textContent=`R$ ${totD.toFixed(2)}`;
  if(e4)e4.textContent=`R$ ${totB.toFixed(2)}`;
  if(e3){e3.textContent=`R$ ${Math.abs(saldo).toFixed(2)}`;e3.style.color=saldo>=0?'#10b981':'#ef4444';}
  if(!data.length){wrap.innerHTML='<div class="card"><div style="padding:48px;text-align:center;color:var(--text3)">Nenhum Registro Encontrado</div></div>';return;}
  const tipoBadge=t=>t==='credito'?`<span style="background:#d1fae5;color:#059669;padding:2px 8px;border-radius:20px;font-size:11px;font-weight:700">Crédito</span>`:t==='bonus'?`<span style="background:#ede9fe;color:#7c3aed;padding:2px 8px;border-radius:20px;font-size:11px;font-weight:700">Bônus</span>`:`<span style="background:#fee2e2;color:#ef4444;padding:2px 8px;border-radius:20px;font-size:11px;font-weight:700">Débito</span>`;
  const colLabel=isLojas?'Loja':'Entregador';
  wrap.innerHTML=`<div class="card"><div style="overflow-x:auto"><table>
    <thead><tr><th>Data</th><th>${colLabel}</th><th>Tipo</th><th>Valor</th><th>Observações</th></tr></thead>
    <tbody>${data.map(r=>`<tr>
      <td style="font-size:12px;color:var(--text3)">${formatarDataHora(r.created_at)}</td>
      <td style="font-weight:600;color:var(--text)">${r[joinField]?.nome||'—'}</td>
      <td>${tipoBadge(r.tipo)}</td>
      <td style="font-weight:700;color:${r.tipo==='credito'?'#10b981':r.tipo==='bonus'?'#7c3aed':'#ef4444'}">R$ ${(parseFloat(r.valor)||0).toFixed(2)}</td>
      <td style="color:var(--text2);font-size:12px">${r.observacoes||'—'}</td>
    </tr>`).join('')}</tbody>
  </table></div></div>`;
}

async function _scAbrirModal(id){
  const isLojas=_scSubAba==='lojas';
  const entidades=await db(isLojas?'lojas':'entregadores','GET',null,'?select=id,nome&order=nome.asc');
  const sel=document.getElementById('sc-m-ent');
  if(sel){
    sel.innerHTML=(Array.isArray(entidades)?entidades:[]).map(e=>`<option value="${e.id}">${e.nome||e.id?.substring(0,8)}</option>`).join('');
    if(id){const opt=sel.querySelector(`option[value="${id}"]`);if(opt)opt.selected=true;}
  }
  const lblWrap=document.getElementById('sc-modal-entidade-wrap');
  if(lblWrap){const lbl=lblWrap.querySelector('label');if(lbl)lbl.textContent=isLojas?'Loja':'Entregador';}
  const titulo=document.getElementById('sc-modal-titulo');
  if(titulo)titulo.textContent=`Cadastrar Crédito / Débito — ${isLojas?'Loja':'Entregador'}`;
  // Loja: recarga passa pela função do servidor (1ª recarga mínima e bônus
  // calculados lá); bônus de loja não é mais lançado à mão.
  const mw=document.getElementById('sc-m-motivo-wrap');if(mw)mw.style.display=isLojas?'block':'none';
  const mo=document.getElementById('sc-m-motivo');if(mo)mo.value='recarga';
  const tp=document.getElementById('sc-m-tipo');
  if(tp)tp.innerHTML=isLojas?'<option value="credito">Credito</option><option value="debito">Debito</option>':'<option value="credito">Credito</option><option value="debito">Debito</option><option value="bonus">Bônus</option>';
  const vl=document.getElementById('sc-m-valor');if(vl)vl.value='';
  _scPreviaCache={};
  _scAtualizarPrevia(true);
  const modal=document.getElementById('modal-sc');
  if(modal)modal.style.display='flex';
}
let _scPreviaCache={};
async function _scAtualizarPrevia(recarregar){
  const isLojas=_scSubAba==='lojas';
  const recarga=isLojas&&document.getElementById('sc-m-motivo')?.value==='recarga';
  const show=(id,v)=>{const el=document.getElementById(id);if(el)el.style.display=v?'block':'none';};
  show('sc-m-tipo-wrap',!recarga);show('sc-m-data-wrap',!recarga);
  const lbl=document.querySelector('#sc-m-valor-wrap label');if(lbl)lbl.textContent=recarga?'Valor Pago Pela Loja':'Valor';
  const box=document.getElementById('sc-m-previa');if(!box)return;
  if(!recarga){box.style.display='none';return;}
  const lojaId=document.getElementById('sc-m-ent')?.value;if(!lojaId){box.style.display='none';return;}
  if(recarregar||!_scPreviaCache[lojaId]){box.style.display='block';box.innerHTML='<div style="font-size:12px;color:var(--text3)">Consultando Regras Da Recarga...</div>';_scPreviaCache[lojaId]=await _rcgCarregarInfo(lojaId);}
  const info=_scPreviaCache[lojaId];
  if(document.getElementById('sc-m-ent')?.value!==lojaId)return;
  const valor=parseFloat(document.getElementById('sc-m-valor')?.value)||0;
  const caixa=(cor,icone,html)=>`<div style="display:flex;gap:8px;align-items:flex-start;border:1px solid ${cor}55;background:${cor}14;border-radius:10px;padding:9px 12px;font-size:12.5px;line-height:1.45;color:var(--text);margin-bottom:8px">${_icone(icone,15)}<div>${html}</div></div>`;
  let h='';
  if(info._semServidor)h+=caixa('#ef4444','circle-alert','<b>Função De Recarga Indisponível No Banco.</b> Aplique a migration da recarga antes de lançar recargas.');
  const min=info.minimo_primeira_recarga||_RCG_MINIMO_PRIMEIRA;
  if(info.primeira_recarga)h+=caixa(valor&&valor<min?'#ef4444':'#3b82f6','info',`<b>Primeira Recarga: Mínimo ${_rcgFmtCurto(min)}.</b>${valor&&valor<min?' O valor informado está abaixo do mínimo e será recusado.':''}`);
  const j=info.janela,pac=_rcgPacotes(info).find(p=>Math.abs(p.pago-valor)<0.005);
  if(j&&j.ativo){
    h+=caixa('#10b981','badge-percent',`<b>Bônus Ativo Até ${_rcgDM(j.fim)}.</b> ${!valor?'Informe o valor pago para ver o bônus.':pac&&pac.bonus>0?`Pacote ${_rcgFmtCurto(pac.pago)}: + ${_rcgFmt(pac.bonus)} de bônus. <b>Total Creditado: ${_rcgFmt(pac.pago+pac.bonus)}</b>.`:`Valor fora dos pacotes com bônus: será creditado só ${_rcgFmt(valor)}.`}`);
  }else if(j){
    h+=caixa('#64748b','calendar',`<b>Bônus Fora Da Janela</b> (próxima: ${_rcgDM(j.proximo_inicio)} a ${_rcgDM(j.proximo_fim)}). Será creditado só o valor pago${valor?': <b>'+_rcgFmt(valor)+'</b>':''}.`);
  }
  h+=`<div style="font-size:11.5px;color:var(--text3)">Data Do Crédito: Hoje. O Bônus É Calculado Pelo Servidor No Momento Do Lançamento.</div>`;
  box.style.display='block';box.innerHTML=h;
}
// RPC com a mensagem de erro do servidor (dbRpc devolve [] em qualquer erro)
async function _dbRpcDetalhe(fn,args){
  try{
    const r=await fetch(`${SB_URL}/rest/v1/rpc/${fn}`,{method:'POST',headers:{'apikey':SB_KEY,'Authorization':await _authHeader(),'Content-Type':'application/json'},body:JSON.stringify(args)});
    const t=await r.text();let j=null;try{j=t?JSON.parse(t):null;}catch{}
    if(!r.ok)return{ok:false,erro:j?.message||`Erro ${r.status}`,hint:j?.hint||null};
    return{ok:true,data:j};
  }catch{return{ok:false,erro:'Erro De Conexão.'};}
}

async function _scSalvar(){
  const isLojas=_scSubAba==='lojas';
  const entId=document.getElementById('sc-m-ent')?.value;
  const data=document.getElementById('sc-m-data')?.value;
  const tipo=document.getElementById('sc-m-tipo')?.value;
  const valor=parseFloat(document.getElementById('sc-m-valor')?.value||0);
  const observacoes=(document.getElementById('sc-m-obs')?.value||'').trim();
  if(isLojas&&document.getElementById('sc-m-motivo')?.value==='recarga'){
    if(!entId||!(valor>0)){showNotif('Atenção','Escolha A Loja E Informe O Valor Pago','var(--yellow)');return;}
    const r=await _dbRpcDetalhe('creditar_recarga_loja',{p_loja_id:entId,p_valor_pago:valor,p_usuario:`${currentUser?.nome||''} (${currentUser?.email||currentPerfil||''})`,p_observacoes:observacoes||null});
    if(!r.ok){showNotif('Recarga Não Lançada',r.erro,'var(--red)');return;}
    const d=r.data||{};
    await logAcao('recarga_loja',{loja_id:entId,valor_pago:valor,bonus:d.bonus,credito_total:d.credito_total,primeira:d.primeira_recarga});
    showNotif('Recarga Lançada',`${_rcgFmt(d.valor_pago)}${d.bonus>0?` + ${_rcgFmt(d.bonus)} De Bônus = ${_rcgFmt(d.credito_total)}`:' (Sem Bônus)'}`);
    document.getElementById('modal-sc').style.display='none';
    _scBuscar();
    return;
  }
  if(!entId||!data||!tipo||!(valor>0)){showNotif('Atenção','Preencha Todos Os Campos Obrigatórios','var(--yellow)');return;}
  const agora=new Date().toISOString();
  const tabela=isLojas?'creditos_lojas':'creditos_entregadores';
  const fkField=isLojas?'loja_id':'entregador_id';
  const payload={[fkField]:entId,tipo,valor,observacoes,data,created_at:agora,updated_at:agora};
  const res=await db(tabela,'POST',payload);
  if(res&&(Array.isArray(res)?res.length>0:res.id)){
    showNotif('✅ Registro Salvo Com Sucesso!','');
    document.getElementById('modal-sc').style.display='none';
    _scBuscar();
  } else {
    showNotif('❌ Erro Ao Salvar',`Verifique as permissões da tabela ${tabela} no Supabase`,'var(--red)');
  }
}

// ── CONTAS A PAGAR ──
let _cpEditId=null;
function _renderContasPagar(){
  const el=document.getElementById('financeiro-content');if(!el)return;
  const mesAtual=new Date().toISOString().slice(0,7);
  el.innerHTML=`
    <div class="card" style="margin-bottom:16px"><div style="padding:16px 20px">
      <div style="font-size:15px;font-weight:700;color:var(--text);margin-bottom:16px" id="cp-form-titulo">Cadastrar Conta A Pagar</div>
      <div style="display:flex;gap:14px;flex-wrap:wrap;align-items:flex-end">
        <div>${_scLabel('Mês/Ano')}<input type="month" id="cp-m-competencia" value="${mesAtual}" style="${_scInput()}"/></div>
        <div style="flex:2;min-width:200px">${_scLabel('Descrição')}<input type="text" id="cp-m-descricao" placeholder="Ex: Aluguel escritório" style="${_scInput()}"/></div>
        <div>${_scLabel('Categoria')}<select id="cp-m-categoria" style="${_scInput()}">
          <option value="Aluguel">Aluguel</option><option value="Internet">Internet</option>
          <option value="Salário">Salário</option><option value="Contador">Contador</option>
          <option value="Marketing">Marketing</option><option value="Outros">Outros</option>
        </select></div>
        <div>${_scLabel('Valor')}<input type="number" id="cp-m-valor" min="0.01" step="0.01" placeholder="0.00" style="${_scInput()}"/></div>
        <div>${_scLabel('Status')}<select id="cp-m-status" style="${_scInput()}"><option value="pendente">Pendente</option><option value="pago">Pago</option></select></div>
        <div>${_scLabel('Vencimento')}<input type="date" id="cp-m-vencimento" style="${_scInput()}"/></div>
        <button id="cp-btn-salvar" onclick="_cpSalvar()" style="background:var(--accent);color:#fff;border:none;border-radius:8px;padding:9px 20px;font-size:13px;font-weight:700;cursor:pointer;font-family:Inter,sans-serif">Salvar</button>
        <button id="cp-btn-cancelar" onclick="_cpCancelarEdicao()" style="display:none;background:none;color:var(--text2);border:1px solid var(--border);border-radius:8px;padding:9px 20px;font-size:13px;font-weight:700;cursor:pointer;font-family:Inter,sans-serif">Cancelar</button>
      </div>
    </div></div>
    <div class="card" style="margin-bottom:16px"><div style="padding:16px 20px">
      <div style="display:flex;gap:14px;align-items:flex-end;flex-wrap:wrap">
        <div>${_scLabel('Filtrar Por Mês')}<input type="month" id="cp-f-mes" style="${_scInput()}"/></div>
        <button onclick="_cpBuscar()" style="background:var(--accent);color:#fff;border:none;border-radius:8px;padding:9px 20px;font-size:13px;font-weight:700;cursor:pointer;font-family:Inter,sans-serif">Buscar</button>
        <button onclick="document.getElementById('cp-f-mes').value='';_cpBuscar()" style="background:none;color:var(--text2);border:1px solid var(--border);border-radius:8px;padding:9px 20px;font-size:13px;font-weight:700;cursor:pointer;font-family:Inter,sans-serif">Limpar</button>
      </div>
    </div></div>
    <div id="cp-tabela"><div style="padding:24px;text-align:center;color:var(--text3)">Carregando...</div></div>
  `;
  _cpBuscar();
}
async function _cpBuscar(){
  const wrap=document.getElementById('cp-tabela');if(!wrap)return;
  wrap.innerHTML='<div style="padding:24px;text-align:center;color:var(--text3)">Buscando...</div>';
  const mes=document.getElementById('cp-f-mes')?.value;
  let qs='?order=competencia.desc,created_at.desc&limit=500';
  if(mes)qs+=`&competencia=eq.${mes}-01`;
  const rows=await db('contas_pagar','GET',null,qs);
  const data=Array.isArray(rows)?rows:[];
  if(!data.length){wrap.innerHTML='<div class="card"><div style="padding:48px;text-align:center;color:var(--text3)">Nenhuma Conta Cadastrada</div></div>';return;}
  const statusBadge=s=>s==='pago'?`<span style="background:#d1fae5;color:#059669;padding:2px 8px;border-radius:20px;font-size:11px;font-weight:700">Pago</span>`:`<span style="background:#fef3c7;color:#92400e;padding:2px 8px;border-radius:20px;font-size:11px;font-weight:700">Pendente</span>`;
  wrap.innerHTML=`<div class="card"><div style="overflow-x:auto"><table>
    <thead><tr><th>Competência</th><th>Descrição</th><th>Categoria</th><th>Valor</th><th>Status</th><th>Vencimento</th><th>Ações</th></tr></thead>
    <tbody>${data.map(r=>`<tr>
      <td style="font-size:12px;color:var(--text3)">${(r.competencia||'').slice(0,7)}</td>
      <td style="font-weight:600;color:var(--text)">${r.descricao||'—'}</td>
      <td style="color:var(--text2);font-size:12px">${r.categoria||'—'}</td>
      <td style="font-weight:700;color:var(--text)">R$ ${(parseFloat(r.valor)||0).toFixed(2)}</td>
      <td>${statusBadge(r.status)}</td>
      <td style="font-size:12px;color:var(--text3)">${r.vencimento?r.vencimento.split('-').reverse().join('/'):'—'}</td>
      <td style="white-space:nowrap"><button onclick="_cpEditar('${r.id}')" style="background:none;border:1px solid var(--border);border-radius:6px;width:28px;height:28px;cursor:pointer;font-size:13px;margin-right:4px">${_icone('pencil',16)}</button><button onclick="_cpExcluir('${r.id}')" style="background:none;border:1px solid #ef4444;border-radius:6px;width:28px;height:28px;cursor:pointer;font-size:13px">${_icone('trash-2',16)}</button></td>
    </tr>`).join('')}</tbody>
  </table></div></div>`;
}
async function _cpSalvar(){
  const mes=document.getElementById('cp-m-competencia')?.value;
  const descricao=(document.getElementById('cp-m-descricao')?.value||'').trim();
  const categoria=document.getElementById('cp-m-categoria')?.value;
  const valor=parseFloat(document.getElementById('cp-m-valor')?.value||0);
  const status=document.getElementById('cp-m-status')?.value;
  const vencimento=document.getElementById('cp-m-vencimento')?.value||null;
  if(!mes||!descricao||!categoria||!(valor>0)){showNotif('Atenção','Preencha Todos Os Campos Obrigatórios','var(--yellow)');return;}
  const agora=new Date().toISOString();
  const payload={competencia:`${mes}-01`,descricao,categoria,valor,status,vencimento,updated_at:agora};
  let res;
  if(_cpEditId){res=await dbPatch('contas_pagar',payload,`?id=eq.${_cpEditId}`);}
  else{payload.created_at=agora;res=await db('contas_pagar','POST',payload);}
  if(res&&(Array.isArray(res)?res.length>0:res.id)){
    showNotif('✅ Conta Salva Com Sucesso!','');
    _cpCancelarEdicao();
    _cpBuscar();
  } else {
    showNotif('❌ Erro Ao Salvar','Verifique as permissões da tabela contas_pagar no Supabase','var(--red)');
  }
}
async function _cpEditar(id){
  const rows=await db('contas_pagar','GET',null,`?id=eq.${id}`);
  const r=Array.isArray(rows)?rows[0]:null;if(!r)return;
  _cpEditId=id;
  const g=(sel)=>document.getElementById(sel);
  if(g('cp-m-competencia'))g('cp-m-competencia').value=(r.competencia||'').slice(0,7);
  if(g('cp-m-descricao'))g('cp-m-descricao').value=r.descricao||'';
  if(g('cp-m-categoria'))g('cp-m-categoria').value=r.categoria||'Outros';
  if(g('cp-m-valor'))g('cp-m-valor').value=r.valor||'';
  if(g('cp-m-status'))g('cp-m-status').value=r.status||'pendente';
  if(g('cp-m-vencimento'))g('cp-m-vencimento').value=r.vencimento||'';
  if(g('cp-form-titulo'))g('cp-form-titulo').textContent='Editar Conta A Pagar';
  if(g('cp-btn-salvar'))g('cp-btn-salvar').textContent='Salvar Edição';
  if(g('cp-btn-cancelar'))g('cp-btn-cancelar').style.display='inline-block';
  window.scrollTo({top:0,behavior:'smooth'});
}
function _cpCancelarEdicao(){
  _cpEditId=null;
  const g=(sel)=>document.getElementById(sel);
  if(g('cp-m-competencia'))g('cp-m-competencia').value=new Date().toISOString().slice(0,7);
  if(g('cp-m-descricao'))g('cp-m-descricao').value='';
  if(g('cp-m-categoria'))g('cp-m-categoria').value='Aluguel';
  if(g('cp-m-valor'))g('cp-m-valor').value='';
  if(g('cp-m-status'))g('cp-m-status').value='pendente';
  if(g('cp-m-vencimento'))g('cp-m-vencimento').value='';
  if(g('cp-form-titulo'))g('cp-form-titulo').textContent='Cadastrar Conta A Pagar';
  if(g('cp-btn-salvar'))g('cp-btn-salvar').textContent='Salvar';
  if(g('cp-btn-cancelar'))g('cp-btn-cancelar').style.display='none';
}
async function _cpExcluir(id){
  if(!confirm('Excluir Esta Conta A Pagar?'))return;
  await db('contas_pagar','DELETE',null,`?id=eq.${id}`);
  showNotif('🗑️ Conta Excluída','','var(--red)');
  _cpBuscar();
}

// ── FATURAS (LOJA) ──
// Mesmos dados de "Histórico de Cobranças" (Financeiro > Aprovar Faturas, no
// painel admin), mas restrito à loja logada. IMPORTANTE: esse filtro
// &loja_id=eq.${currentUser.loja_id} é só client-side, como em todo o resto
// do painel (db() sempre usa a chave anon estática, nunca o JWT da sessão) —
// não é uma garantia de RLS a nível de banco. Ver conversa/memória sobre a
// auditoria de RLS/anon-vs-JWT pendente.
// ── Financeiro da loja (2026-09-30) ──
// Loja de CRÉDITO: saldo + Recarregar no topo, "Extrato do Crédito"
// (creditos_lojas: recarga, bônus, débito de entrega agrupado por dia,
// estorno, ajuste; saldo após cada lançamento; filtro por período e tipo;
// paginação) e "Faturas Anteriores" (histórico de quando a loja faturava).
// Loja de FATURAMENTO: tela de sempre (só faturas), sem mudança.
// Só leitura. Admin/suporte abrem pela lista de Lojas (abrirFinanceiroLoja).
// Saldo = mesma conta do botão de saldo (soma de creditos_lojas); se a loja
// tiver credito_desde (migration da troca, ainda não aplicada), conta só a
// partir dela.
const _FIN_POR_PAGINA=15;
let _fin={lojaId:null,loja:null,equipe:false,linhas:[],grupos:[],pagina:0,filtro:{ini:'',fim:'',tipo:''},abertos:new Set()};
const _FIN_TIPOS=[['','Todos Os Tipos'],['recarga','Recarga Pix'],['bonus','Bônus'],['entrega','Débito De Entrega'],['estorno','Estorno De Entrega'],['ajuste','Ajuste']];
function _finTipo(r){
  if(r.tipo==='bonus')return'bonus';
  const o=r.origem||'';
  if(o==='recarga')return'recarga';
  if(o==='entrega'||(r.tipo==='debito'&&/^entrega #/i.test(r.observacoes||'')))return'entrega';
  if(o==='estorno'||(r.tipo==='credito'&&/^estorno #/i.test(r.observacoes||'')))return'estorno';
  if(!o&&r.tipo==='credito')return'recarga';
  return'ajuste';
}
function _finRotulo(t){return(_FIN_TIPOS.find(x=>x[0]===t)||['','Ajuste'])[1];}
function _finSinal(r){return r.tipo==='debito'?-1:1;}
function _finEstilos(){
  if(document.getElementById('fin-styles'))return;
  const st=document.createElement('style');st.id='fin-styles';
  st.textContent=`
  .fin-topo{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:20px 22px}
  .fin-saldo span{display:block;font-size:11px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:var(--text3)}
  .fin-saldo b{display:block;font-size:30px;font-weight:800;margin-top:2px;letter-spacing:-.5px}
  .fin-saldo small{display:block;font-size:12.5px;color:var(--text2);margin-top:4px}
  .fin-btn{display:inline-flex;align-items:center;gap:8px;height:42px;padding:0 18px;border:none;border-radius:10px;background:var(--accent);color:#fff;font:700 14px Inter,sans-serif;cursor:pointer}
  .fin-btn:hover{background:#1646b5}.fin-btn:focus-visible{outline:none;box-shadow:0 0 0 3px rgba(26,86,219,.45)}
  .fin-filtros{display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;padding:14px 18px;border-bottom:1px solid var(--border)}
  .fin-filtros label{display:block;font-size:11px;font-weight:600;color:var(--text2);margin-bottom:5px;letter-spacing:.3px}
  .fin-filtros input,.fin-filtros select{height:38px;background:var(--surface2);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:0 10px;font:13px Inter,sans-serif}
  .fin-lista{display:flex;flex-direction:column}
  .fin-linha{display:grid;grid-template-columns:96px 150px 1fr 120px 120px;gap:12px;align-items:center;padding:12px 18px;border-bottom:1px solid var(--border);font-size:13px}
  .fin-linha.cab{font-size:11px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:var(--text3);padding-top:10px;padding-bottom:10px}
  .fin-linha .v{text-align:right;font-weight:700}.fin-linha .s{text-align:right;color:var(--text2)}
  .fin-tag{display:inline-flex;align-items:center;gap:6px;font-weight:600;color:var(--text)}
  .fin-tag i{width:8px;height:8px;border-radius:50%;display:inline-block;flex-shrink:0}
  .fin-desc{color:var(--text2);min-width:0;overflow:hidden;text-overflow:ellipsis}
  .fin-exp{background:none;border:none;color:var(--accent);font:600 12.5px Inter,sans-serif;cursor:pointer;padding:0;display:inline-flex;align-items:center;gap:4px}
  .fin-sub{background:var(--surface2);padding:4px 18px 8px 126px;border-bottom:1px solid var(--border)}
  .fin-sub div{display:flex;justify-content:space-between;font-size:12.5px;color:var(--text2);padding:4px 0}
  .fin-pag{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 18px;font-size:12.5px;color:var(--text2)}
  .fin-pag button{height:34px;padding:0 14px;border-radius:8px;border:1px solid var(--border);background:transparent;color:var(--text);font:600 12.5px Inter,sans-serif;cursor:pointer}
  .fin-pag button[disabled]{opacity:.4;cursor:default}
  .fin-vazio{padding:48px 20px;text-align:center}
  .fin-vazio .ic{width:56px;height:56px;border-radius:16px;margin:0 auto 14px;display:flex;align-items:center;justify-content:center;background:rgba(26,86,219,.14);color:var(--accent)}
  .fin-vazio b{display:block;font-size:15px;color:var(--text);margin-bottom:6px}
  .fin-vazio p{margin:0 auto 16px;max-width:380px;font-size:13px;color:var(--text2);line-height:1.5}
  @media (max-width:760px){
    .fin-linha{grid-template-columns:1fr auto;grid-template-areas:"tipo valor" "desc saldo" "data data";gap:4px 10px;padding:12px 14px}
    .fin-linha.cab{display:none}
    .fin-linha .d{grid-area:data;font-size:11.5px;color:var(--text3)}
    .fin-linha .t{grid-area:tipo}.fin-linha .fin-desc{grid-area:desc;font-size:12.5px}
    .fin-linha .v{grid-area:valor}.fin-linha .s{grid-area:saldo;font-size:12px}
    .fin-sub{padding:4px 14px 8px 14px}
    .fin-saldo b{font-size:26px}
    .fin-topo .fin-btn{width:100%;justify-content:center}
  }`;
  document.head.appendChild(st);
}
// Admin/suporte: abre o Financeiro de uma loja específica.
let _finVoltarPara='lojas';
function abrirFinanceiroLoja(lojaId){_finVoltarPara=_navAtivo||'lojas';renderFaturasLojaPage(lojaId);}
async function renderFaturasLojaPage(lojaIdEquipe){
  const lojaId=(typeof lojaIdEquipe==='string'&&lojaIdEquipe)||currentUser?.loja_id;
  const body=document.getElementById('app-body');
  if(!lojaId){body.innerHTML='<div class="alt-page"><div class="page-header"><div class="page-title">'+_icone('receipt',22)+' Financeiro</div></div><div class="card" style="padding:32px;text-align:center;color:var(--text3)">Nenhuma Loja Associada Ao Seu Usuário.</div></div>';return;}
  const equipe=lojaId!==currentUser?.loja_id;
  const lr=await db('lojas','GET',null,`?id=eq.${lojaId}&select=*`);
  const loja=Array.isArray(lr)&&lr[0]?lr[0]:{id:lojaId,tipo_cobranca:'faturamento'};
  const cab=`<div class="page-header"><div class="page-title">${_icone('receipt',22)} Financeiro${equipe?` — ${_escHtml(loja.nome||'')}`:''}</div>${equipe?`<button class="btn-sm" onclick="goTab(_finVoltarPara)" style="display:inline-flex;align-items:center;gap:6px">${_icone('arrow-left',16)}Voltar</button>`:''}</div>`;
  if(loja.tipo_cobranca!=='credito'){
    // Faturamento: tela de sempre
    body.innerHTML=`<div class="alt-page">
      ${cab}
      <div id="fl-atual"></div>
      <div class="card"><div class="card-header"><span class="card-title">📜 Histórico</span></div><div id="fl-tabela"><div style="padding:32px;text-align:center;color:var(--text3)">Buscando...</div></div></div>
    </div>`;
    _flBuscar(lojaId);
    return;
  }
  _finEstilos();
  _fin={lojaId,loja,equipe,linhas:[],grupos:[],pagina:0,filtro:{ini:'',fim:'',tipo:''},abertos:new Set()};
  body.innerHTML=`<div class="alt-page">
    ${cab}
    <div class="card" style="margin-bottom:16px"><div class="fin-topo" id="fin-topo"><div class="fin-saldo"><span>Saldo Do Crédito</span><b>—</b><small>Carregando...</small></div></div></div>
    <div class="card" style="margin-bottom:16px"><div class="card-header"><span class="card-title">${_icone('wallet',18)} Extrato Do Crédito</span></div>
      <div class="fin-filtros">
        <div><label for="fin-ini">Data Início</label><input type="date" id="fin-ini" onchange="_finFiltrar()"/></div>
        <div><label for="fin-fim">Data Fim</label><input type="date" id="fin-fim" onchange="_finFiltrar()"/></div>
        <div><label for="fin-tipo">Tipo</label><select id="fin-tipo" onchange="_finFiltrar()">${_FIN_TIPOS.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></div>
      </div>
      <div id="fin-extrato"><div style="padding:32px;text-align:center;color:var(--text3)">Carregando...</div></div>
    </div>
    <div id="fin-faturas-wrap" style="display:none">
      <div id="fl-atual"></div>
      <div class="card"><div class="card-header"><span class="card-title">📜 Faturas Anteriores</span></div><div id="fl-tabela"></div></div>
    </div>
  </div>`;
  // extrato (todas as linhas da loja; saldo após = acumulado cronológico)
  let rows=await _dbTodasLinhas('creditos_lojas',`?loja_id=eq.${lojaId}&select=id,tipo,valor,observacoes,data,created_at,origem&order=created_at.asc,id.asc`);
  if(!Array.isArray(rows))rows=[];
  if(loja.credito_desde)rows=rows.filter(r=>r.created_at>=loja.credito_desde);
  let acc=0;
  _fin.linhas=rows.map(r=>{acc=Math.round((acc+_finSinal(r)*(parseFloat(r.valor)||0))*100)/100;return{...r,_t:_finTipo(r),_saldo:acc};});
  _finRenderTopo(acc);
  _finFiltrar();
  // faturas antigas (lojas que já faturaram)
  const fw=document.getElementById('fin-faturas-wrap');
  const fat=await db('cobrancas_lojas','GET',null,`?select=id&loja_id=eq.${lojaId}&limit=1`);
  if(fw&&Array.isArray(fat)&&fat.length){fw.style.display='block';_flBuscar(lojaId);}
}
function _finRenderTopo(saldo){
  const el=document.getElementById('fin-topo');if(!el)return;
  const cor=saldo>=0?'#10b981':'#ef4444';
  el.innerHTML=`<div class="fin-saldo"><span>Saldo Do Crédito</span><b style="color:${cor}">${saldo<0?'-':''}${_rcgFmt(Math.abs(saldo))}</b>
      <small>${saldo<=0?'Recarregue Para Continuar Pedindo Entregas.':'Cada Entrega É Descontada Deste Saldo.'}</small></div>
    <button class="fin-btn" onclick="_abrirModalRecargaPix()">${_icone('wallet',18)}Recarregar</button>`;
}
// agrupa: débitos de entrega do mesmo dia viram uma linha (expansível)
function _finAgrupar(linhas){
  const grupos=[];
  for(const r of linhas){ // linhas em ordem cronológica
    const ult=grupos[grupos.length-1];
    if(r._t==='entrega'&&ult&&ult.entrega&&ult.data===r.data){ult.itens.push(r);ult.valor+=parseFloat(r.valor)||0;ult._saldo=r._saldo;continue;}
    grupos.push(r._t==='entrega'?{entrega:true,data:r.data,itens:[r],valor:parseFloat(r.valor)||0,_saldo:r._saldo,id:'g'+r.id}:{...r,itens:null});
  }
  return grupos.reverse(); // mais recente primeiro
}
function _finFiltrar(){
  _fin.filtro={ini:document.getElementById('fin-ini')?.value||'',fim:document.getElementById('fin-fim')?.value||'',tipo:document.getElementById('fin-tipo')?.value||''};
  const f=_fin.filtro;
  const linhas=_fin.linhas.filter(r=>(!f.ini||String(r.data)>=f.ini)&&(!f.fim||String(r.data)<=f.fim)&&(!f.tipo||r._t===f.tipo));
  _fin.grupos=_finAgrupar(linhas);_fin.pagina=0;_finRenderExtrato();
}
function _finPagina(d){_fin.pagina+=d;_finRenderExtrato();document.getElementById('fin-extrato')?.scrollIntoView({block:'start',behavior:'smooth'});}
function _finToggle(id){_fin.abertos.has(id)?_fin.abertos.delete(id):_fin.abertos.add(id);_finRenderExtrato();}
function _finRenderExtrato(){
  const el=document.getElementById('fin-extrato');if(!el)return;
  if(!_fin.linhas.length){
    el.innerHTML=`<div class="fin-vazio"><div class="ic">${_icone('wallet',26)}</div><b>Nenhuma Movimentação Ainda</b>
      <p>${_fin.equipe?'Esta Loja Ainda Não Tem Lançamentos De Crédito.':'Faça Sua Primeira Recarga Via Pix: O Valor Entra Como Crédito E Cada Entrega É Descontada Dele.'}</p>
      <button class="fin-btn" onclick="_abrirModalRecargaPix()">${_icone('wallet',18)}Recarregar</button></div>`;return;
  }
  if(!_fin.grupos.length){el.innerHTML='<div class="fin-vazio"><b>Nenhum Lançamento Nesse Filtro</b><p>Ajuste O Período Ou O Tipo Para Ver Outros Lançamentos.</p></div>';return;}
  const tot=_fin.grupos.length,pags=Math.ceil(tot/_FIN_POR_PAGINA);
  if(_fin.pagina>=pags)_fin.pagina=pags-1;
  const ini=_fin.pagina*_FIN_POR_PAGINA,pag=_fin.grupos.slice(ini,ini+_FIN_POR_PAGINA);
  const cor={recarga:'#10b981',bonus:'#f59e0b',entrega:'#ef4444',estorno:'#3b82f6',ajuste:'#94a3b8'};
  const sal=v=>v<0?`<span style="color:#ef4444">-${_rcgFmt(-v)}</span>`:_rcgFmt(v);
  const val=(v,sinal)=>`<span style="color:${sinal<0?'#ef4444':'#10b981'}">${sinal<0?'−':'+'} ${_rcgFmt(Math.abs(v))}</span>`;
  const linha=g=>{
    if(g.entrega){
      const aberto=_fin.abertos.has(g.id),n=g.itens.length;
      return`<div class="fin-linha"><span class="d">${formatarDataBR(g.data)}</span><span class="t fin-tag"><i style="background:${cor.entrega}"></i>Débito De Entrega</span>
        <span class="fin-desc">${n} entrega${n>1?'s':''} no dia <button class="fin-exp" aria-expanded="${aberto}" onclick="_finToggle('${g.id}')">${aberto?'Ocultar':'Ver Pedidos'} ${_icone(aberto?'chevron-up':'chevron-down',14)}</button></span>
        <span class="v">${val(g.valor,-1)}</span><span class="s">${sal(g._saldo)}</span></div>
        ${aberto?`<div class="fin-sub">${g.itens.slice().reverse().map(r=>`<div><span>${_escHtml(r.observacoes||'Entrega')}</span><span>− ${_rcgFmt(r.valor)}</span></div>`).join('')}</div>`:''}`;
    }
    return`<div class="fin-linha"><span class="d">${formatarDataBR(g.data)}</span><span class="t fin-tag"><i style="background:${cor[g._t]}"></i>${_finRotulo(g._t)}</span>
      <span class="fin-desc" title="${_escHtml(g.observacoes||'').replace(/"/g,'&quot;')}">${_escHtml(g.observacoes||'—')}</span>
      <span class="v">${val(g.valor,_finSinal(g))}</span><span class="s">${sal(g._saldo)}</span></div>`;
  };
  el.innerHTML=`<div class="fin-lista"><div class="fin-linha cab"><span>Data</span><span>Tipo</span><span>Descrição</span><span class="v">Valor</span><span class="s">Saldo Após</span></div>${pag.map(linha).join('')}</div>
    <div class="fin-pag"><span>${ini+1}–${Math.min(ini+_FIN_POR_PAGINA,tot)} de ${tot}</span><div style="display:flex;gap:8px">
      <button onclick="_finPagina(-1)" ${_fin.pagina===0?'disabled':''}>${_icone('chevron-left',14)} Mais Recentes</button>
      <button onclick="_finPagina(1)" ${_fin.pagina>=pags-1?'disabled':''}>Mais Antigos ${_icone('chevron-right',14)}</button></div></div>`;
}

// Fatura Atual = cobrança pendente mais urgente (maior atraso) da loja —
// normalmente só existe 0 ou 1 (Gerar Cobrança não deixa gerar duas pro
// mesmo período/loja), mas se houver mais de uma pendente por algum motivo,
// as demais continuam aparecendo no Histórico (só saem de "pendente" quando
// pagas/recusadas, igual antes).
async function _flBuscar(lojaId){
  lojaId=lojaId||currentUser?.loja_id;
  const atualWrap=document.getElementById('fl-atual');
  const histWrap=document.getElementById('fl-tabela');if(!histWrap)return;
  const qs=`?select=*&loja_id=eq.${lojaId}&status=in.(pendente,pago,recusado)&order=created_at.desc&limit=200`;
  const rows=await db('cobrancas_lojas','GET',null,qs);
  const todas=Array.isArray(rows)?rows:[];
  const pendentes=todas.filter(c=>c.status==='pendente');
  let atual=null;
  if(pendentes.length){
    const anotadas=pendentes.map(c=>{const vencYMD=_faturaVencimentoYMD(c);return{...c,_vencYMD:vencYMD,_diasAtraso:_diasAtrasoFatura(vencYMD)};});
    anotadas.sort((a,b)=>b._diasAtraso-a._diasAtraso);
    atual=anotadas[0];
  }
  if(atualWrap)atualWrap.innerHTML=atual?_renderFaturaAtualCard(atual):'';
  const hist=todas.filter(c=>c.id!==atual?.id);
  if(!hist.length){histWrap.innerHTML='<div style="padding:48px;text-align:center;color:var(--text3)">Nenhuma Fatura No Histórico</div>';return;}
  const badge=c=>c.status==='pago'
    ?`<span style="background:#d1fae5;color:#059669;padding:2px 10px;border-radius:20px;font-size:11px;font-weight:700">✅ Pago</span>`
    :c.status==='pendente'
    ?`<span style="background:#fef3c7;color:#92400e;padding:2px 10px;border-radius:20px;font-size:11px;font-weight:700">⏳ Pendente</span>`
    :`<span style="background:#fee2e2;color:#ef4444;padding:2px 10px;border-radius:20px;font-size:11px;font-weight:700">❌ Recusado</span>`;
  histWrap.innerHTML=`<div style="overflow-x:auto"><table>
    <thead><tr><th>Data</th><th>Período</th><th>Valor</th><th>Status</th><th>Ver Fatura</th></tr></thead>
    <tbody>${hist.map(c=>`<tr>
      <td style="font-size:12px;color:var(--text3)">${formatarDataHora(c.updated_at||c.created_at)}</td>
      <td style="font-size:12px;color:var(--text2)">${formatarDataBR(c.data_inicio)} – ${formatarDataBR(c.data_fim)}</td>
      <td style="font-weight:700;color:#1A56DB">R$ ${(parseFloat(c.status==='pago'&&c.valor_pago_final!=null?c.valor_pago_final:c.valor_total)||0).toFixed(2)}${c.status==='pago'&&c.valor_pago_final!=null&&c.valor_pago_final!==c.valor_total?`<div style="font-size:10px;font-weight:600;color:var(--text3)">orig. R$ ${(parseFloat(c.valor_total)||0).toFixed(2)}</div>`:''}</td>
      <td>${badge(c)}</td>
      <td><button onclick="verFaturaCobranca('${c.id}')" style="background:none;border:1px solid var(--border);color:var(--text2);border-radius:8px;padding:6px 12px;font-size:12px;font-weight:600;cursor:pointer;font-family:Inter,sans-serif;white-space:nowrap">${_icone('file-text',16,'btn-ico')}Ver Fatura</button></td>
    </tr>`).join('')}</tbody>
  </table></div>`;
}
function _renderFaturaAtualCard(c){
  const {diasAtraso,valorAtualizado}=_calcularJurosMultaFatura(c.valor_total,c._vencYMD);
  const vencida=diasAtraso>=1;
  // Card resumido de propósito: só o valor total já atualizado em
  // destaque, sem o detalhamento linha a linha de multa/juros — esse
  // breakdown completo continua só no modal "Ver Fatura"
  // (verFaturaCobranca) e na tabela "Aprovar Faturas" do admin
  // (_buscarCobrancasPendentes), que já usam _calcularJurosMultaFatura
  // de forma independente.
  return`<div class="card" style="margin-bottom:14px;border:2px solid ${vencida?'#ef4444':'var(--accent)'}">
    <div class="card-header"><span class="card-title">${vencida?'🔴':'🟡'} Fatura Atual</span></div>
    <div style="padding:20px">
      <div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:16px;margin-bottom:16px">
        <div><div style="font-size:11px;color:var(--text3);text-transform:uppercase;letter-spacing:.4px">Período</div><div style="font-size:14px;font-weight:600;color:var(--text)">${formatarDataBR(c.data_inicio)} – ${formatarDataBR(c.data_fim)}</div></div>
        <div><div style="font-size:11px;color:var(--text3);text-transform:uppercase;letter-spacing:.4px">Vencimento</div><div style="font-size:14px;font-weight:600;color:${vencida?'#ef4444':'var(--text)'}">${formatarDataBR(c._vencYMD)}${vencida?` · ${diasAtraso} dia${diasAtraso>1?'s':''} de atraso`:''}</div></div>
      </div>
      ${vencida?`<div style="font-size:28px;font-weight:800;color:#dc2626;margin-bottom:16px">R$ ${valorAtualizado.toFixed(2)}</div>`:`<div style="font-size:28px;font-weight:800;color:#1A56DB;margin-bottom:16px">R$ ${(parseFloat(c.valor_total)||0).toFixed(2)}</div>`}
      <button onclick="verFaturaCobranca('${c.id}')" style="background:#6366f1;color:#fff;border:none;border-radius:8px;padding:9px 20px;font-size:13px;font-weight:700;cursor:pointer;font-family:Inter,sans-serif">${_icone('file-text',16,'btn-ico')}Ver Fatura</button>
    </div>
  </div>`;
}

// ── RANKING ENTREGADOR ──
const _RANKING_PREMIOS=[100,80,70,60,50,40,30,20,15,10];
let _rankingAba='ranking';
async function renderRankingPage(aba){
  _rankingAba=aba||_rankingAba||'ranking';
  const abas=[{id:'ranking',icon:'trophy',label:'Ranking'},{id:'clas',icon:'crown',label:'Clãs'}];
  document.getElementById('app-body').innerHTML=`<div class="alt-page">
    <div class="page-header"><div class="page-title">${_icone('trophy',22)} Ranking Entregador</div></div>
    <div style="display:flex;gap:0;margin-bottom:20px;border-bottom:1px solid var(--border);overflow-x:auto;flex-wrap:nowrap">
      ${abas.map(a=>`<button onclick="renderRankingPage('${a.id}')" style="padding:10px 18px;border:none;background:none;font-family:Inter,sans-serif;font-size:13px;font-weight:600;cursor:pointer;white-space:nowrap;border-bottom:2px solid ${_rankingAba===a.id?'var(--accent)':'transparent'};color:${_rankingAba===a.id?'var(--accent)':'var(--text3)'}">${_icone(a.icon,16,'btn-ico')}${a.label}</button>`).join('')}
    </div>
    <div id="ranking-content"></div>
  </div>`;
  if(_rankingAba==='clas'){_renderClasTab();return;}
  _renderRankingLista();
}

async function _renderRankingLista(){
  const el=document.getElementById('ranking-content');if(!el)return;
  el.innerHTML=`<div class="card"><div style="padding:16px 20px;font-size:12px;color:var(--text3)">Top 10 Da Semana Atual Por Pontos — Só Informativo, Sem Pagamento Automático.</div><div id="ranking-lista"><div style="padding:32px;text-align:center;color:var(--text3)">Carregando...</div></div></div>`;
  const entregadores=await db('entregadores','GET',null,'?select=id,nome,pontos_semana&pontos_semana=gt.0&order=pontos_semana.desc&limit=10');
  const lista=document.getElementById('ranking-lista');if(!lista)return;
  const arr=Array.isArray(entregadores)?entregadores:[];
  if(!arr.length){lista.innerHTML='<div style="padding:32px;text-align:center;color:var(--text3)">Nenhum Entregador Com Pontos Ainda</div>';return;}
  const medalha=(i)=>i===0?'🥇':i===1?'🥈':i===2?'🥉':`${i+1}º`;
  lista.innerHTML=`<div style="overflow-x:auto"><table><thead><tr><th>Posição</th><th>Entregador</th><th>Pontos (Semana)</th><th>Prêmio</th></tr></thead><tbody>${arr.map((e,i)=>`<tr>
    <td style="font-weight:800;font-size:16px">${medalha(i)}</td>
    <td style="font-weight:600;color:var(--text)">${e.nome||e.id?.substring(0,8)||'—'}</td>
    <td style="font-weight:700;color:var(--accent)">${e.pontos_semana??0}</td>
    <td style="font-weight:700;color:#22c55e">R$ ${(_RANKING_PREMIOS[i]||0).toFixed(2)}</td>
  </tr>`).join('')}</tbody></table></div>`;
}

// ── CLÃS DE ENTREGADOR ──
// Grupo exclusivo loja(s)+entregador(es) por cidade — regra de despacho, não
// só rótulo (ver migrations/add_clas_entregador.sql e entregadores_no_raio).
// Cardinalidade 1:1: uma loja/entregador pertence a no máximo 1 clã — os
// pickers abaixo escondem quem já está em outro clã, pra não dar pra
// selecionar de novo (mesma regra que o banco já garante via UNIQUE).
const _UF_LIST=['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];
let _clasCache=[],_clasLojasCache=[],_clasEntCache=[];
let _claVerCache={};

async function _renderClasTab(){
  const el=document.getElementById('ranking-content');if(!el)return;
  el.innerHTML='<div style="padding:32px;text-align:center;color:var(--text3)">Carregando...</div>';
  const [lojas,entregadores,clas,clasLojas,clasEnt]=await Promise.all([
    db('lojas','GET',null,'?select=id,nome,cidade&order=nome.asc'),
    db('entregadores','GET',null,'?select=id,nome,cpf&order=nome.asc'),
    db('clas','GET',null,'?order=cidade.asc'),
    db('clas_lojas','GET',null,''),
    db('clas_entregadores','GET',null,''),
  ]);
  _clasCache=Array.isArray(clas)?clas:[];
  _clasLojasCache=Array.isArray(clasLojas)?clasLojas:[];
  _clasEntCache=Array.isArray(clasEnt)?clasEnt:[];
  const lojasAll=Array.isArray(lojas)?lojas:[];
  const entAll=Array.isArray(entregadores)?entregadores:[];
  const cidades=[...new Set(lojasAll.map(l=>l.cidade).filter(Boolean))].sort();
  const elFinal=document.getElementById('ranking-content');if(!elFinal)return;
  if(!cidades.length){elFinal.innerHTML='<div class="card"><div style="padding:32px;text-align:center;color:var(--text3)">Nenhuma Cidade Com Loja Cadastrada Ainda.</div></div>';return;}
  elFinal.innerHTML=`<div style="display:flex;flex-direction:column;gap:16px">${cidades.map(c=>_claCardHtml(c,lojasAll,entAll)).join('')}</div>`;
}

function _claCardHtml(cidade,lojasAll,entAll){
  const cla=_clasCache.find(c=>c.cidade===cidade);
  const cidSafe=cidade.replace(/[^a-z0-9]/gi,'_');
  const cidadeEsc=cidade.replace(/'/g,"\\'");
  if(!cla){
    return `<div class="card"><div style="padding:20px 24px">
      <div style="font-size:15px;font-weight:800;color:var(--text);margin-bottom:4px">${cidade}</div>
      <div style="font-size:12px;color:var(--text3);margin-bottom:14px">Nenhum Clã Criado Pra Essa Cidade Ainda.</div>
      <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap">
        <select id="cla-uf-${cidSafe}" style="${_ss};max-width:100px">${_UF_LIST.map(u=>`<option value="${u}">${u}</option>`).join('')}</select>
        <button class="btn-modal-primary" onclick="_criarCla('${cidadeEsc}','${cidSafe}')">${_icone('plus',16,'btn-ico')}Criar Clã De ${cidade}</button>
      </div>
    </div></div>`;
  }
  const lojasDoCla=_clasLojasCache.filter(cl=>cl.cla_id===cla.id).map(cl=>cl.loja_id);
  const entDoCla=_clasEntCache.filter(ce=>ce.cla_id===cla.id).map(ce=>ce.entregador_id);
  const lojasOcupadas=new Set(_clasLojasCache.filter(cl=>cl.cla_id!==cla.id).map(cl=>cl.loja_id));
  const entOcupados=new Set(_clasEntCache.filter(ce=>ce.cla_id!==cla.id).map(ce=>ce.entregador_id));
  const lojasDisponiveis=lojasAll.filter(l=>!lojasOcupadas.has(l.id));
  const entDisponiveis=entAll.filter(e=>!entOcupados.has(e.id));
  return `<div class="card"><div style="padding:20px 24px">
    <div style="font-size:15px;font-weight:800;color:var(--text);margin-bottom:14px">👑 ${cidade.toUpperCase()} - ${cla.uf}</div>
    ${_claPickerHtml('loja',cidSafe,lojasDisponiveis,lojasDoCla)}
    ${_claPickerHtml('ent',cidSafe,entDisponiveis,entDoCla)}
    <div id="cla-feedback-${cidSafe}" style="margin:10px 0;font-size:12px"></div>
    <button class="btn-modal-primary" onclick="_salvarCla('${cla.id}','${cidSafe}')">${_icone('save',16,'btn-ico')}Salvar</button>
  </div></div>`;
}

function _claPickerHtml(tipo,cidSafe,entidades,selecionadosIds){
  const label=tipo==='loja'?`🏪 Lojas do clã (${selecionadosIds.length})`:`🛵 Entregadores do clã (${selecionadosIds.length})`;
  const verLabel=tipo==='loja'?'Ver Lojas':'Ver Entregadores';
  const multiId=`cla-multi-${tipo}-${cidSafe}`;
  _claVerCache[multiId]=entidades.filter(e=>selecionadosIds.includes(e.id)).map(e=>e.nome);
  const optionsHtml=entidades.map(e=>`<label class="cla-opt" data-doc="${tipo==='ent'?(e.cpf||'').replace(/\D/g,''):''}" style="display:flex;align-items:center;gap:8px;padding:4px 0;cursor:pointer;font-size:13px"><input type="checkbox" value="${e.id}" ${selecionadosIds.includes(e.id)?'checked':''} style="width:14px;height:14px;cursor:pointer"/>${e.nome}</label>`).join('');
  return `<div class="fi" style="margin-bottom:14px">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">
      <label style="margin:0">${label}</label>
      <span onclick="_claVerLista('${multiId}','${verLabel}')" style="font-size:11px;color:var(--accent);cursor:pointer;font-weight:600;user-select:none">👁️ ${verLabel}</span>
    </div>
    <input type="text" placeholder="Buscar..." oninput="_claFiltrarOpcoes('${multiId}',this.value)"
      style="width:100%;padding:7px 10px;border:1px solid var(--border);border-radius:8px 8px 0 0;font-size:12px;background:var(--surface2);color:var(--text);font-family:Inter,sans-serif;box-sizing:border-box;outline:none;border-bottom:none"/>
    <div id="${multiId}" style="max-height:160px;overflow-y:auto;border:1px solid var(--border);border-radius:0 0 8px 8px;padding:6px 10px;background:var(--surface2)">
      ${optionsHtml||'<div style="color:var(--text3);font-size:12px">Nenhum Disponível (Todos Já Estão Em Outro Clã)</div>'}
    </div>
  </div>`;
}
// Popup simples com os nomes já selecionados naquele picker no momento em
// que _claPickerHtml renderizou (_claVerCache[multiId]) — não lê os
// checkboxes ao vivo de propósito: é "o que está salvo", não "o que está
// marcado na tela sem ter salvo ainda" (evita confundir seleção pendente
// com o que já é clã de verdade). Mesmo padrão de modal dinâmico já usado
// em abrirAlocarMotoboy (cria/reaproveita a div, sem depender de markup
// fixo no index.html).
function _claVerLista(multiId,verLabel){
  const nomes=_claVerCache[multiId]||[];
  let modal=document.getElementById('modal-cla-ver-lista');
  if(!modal){modal=document.createElement('div');modal.id='modal-cla-ver-lista';modal.className='modal-overlay';document.body.appendChild(modal);}
  const listaHtml=nomes.length
    ?nomes.map(n=>`<div style="padding:9px 2px;border-bottom:1px solid var(--border);font-size:13px;color:var(--text)">${n}</div>`).join('')
    :`<div style="text-align:center;padding:24px;color:var(--text3)">Nenhum Selecionado Ainda</div>`;
  modal.innerHTML=`<div class="modal"><div class="modal-header"><span class="modal-title">${verLabel} (${nomes.length})</span><button class="modal-close" onclick="fecharModal('modal-cla-ver-lista')">${_icone('x',16)}</button></div><div class="modal-body" style="max-height:340px;overflow-y:auto">${listaHtml}</div></div>`;
  modal.classList.add('open');
  modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open');};
}

// Busca por nome OU documento (CPF, hoje só disponível pra entregadores —
// lojas não têm nenhum campo de CNPJ cadastrado no banco, confirmado nas
// colunas de public.lojas). Documento comparado só por dígitos, sem exigir
// a formatação exata (com ou sem pontuação bate igual).
function _claFiltrarOpcoes(multiId,busca){
  const q=(busca||'').trim().toLowerCase();
  const qDigits=q.replace(/\D/g,'');
  const wrap=document.getElementById(multiId);if(!wrap)return;
  wrap.querySelectorAll('.cla-opt').forEach(lbl=>{
    const nome=lbl.textContent.toLowerCase();
    const doc=lbl.dataset.doc||'';
    const match=!q||nome.includes(q)||(!!qDigits&&doc.includes(qDigits));
    lbl.style.display=match?'':'none';
  });
}

async function _criarCla(cidade,cidSafe){
  const uf=document.getElementById(`cla-uf-${cidSafe}`)?.value;if(!uf)return;
  const res=await db('clas','POST',{cidade,uf});
  if(!Array.isArray(res)||!res.length){showNotif('❌ Erro Ao Criar Clã','','var(--red)');return;}
  showNotif('✅ Clã Criado','','var(--green)');
  _renderClasTab();
}

async function _salvarCla(claId,cidSafe){
  const fb=document.getElementById(`cla-feedback-${cidSafe}`);
  if(fb)fb.innerHTML='<span style="color:var(--text3)">Salvando…</span>';
  const lojaIds=[...document.querySelectorAll(`#cla-multi-loja-${cidSafe} input[type=checkbox]:checked`)].map(cb=>cb.value);
  const entIds=[...document.querySelectorAll(`#cla-multi-ent-${cidSafe} input[type=checkbox]:checked`)].map(cb=>cb.value);
  await db('clas_lojas','DELETE',null,`?cla_id=eq.${claId}`);
  await db('clas_entregadores','DELETE',null,`?cla_id=eq.${claId}`);
  if(lojaIds.length)await db('clas_lojas','POST',lojaIds.map(id=>({cla_id:claId,loja_id:id})));
  if(entIds.length)await db('clas_entregadores','POST',entIds.map(id=>({cla_id:claId,entregador_id:id})));
  if(fb)fb.innerHTML='<span style="color:#22c55e">✅ Salvo!</span>';
  showNotif('✅ Clã Atualizado','','var(--green)');
  setTimeout(_renderClasTab,900);
}

// ── VAGAS DE MOTOBOY FIXO ──
let _vagasAno=new Date().getFullYear(),_vagasMes=new Date().getMonth();
let _vagasDoMes=[],_feriadosCache=[],_vagasLojas=[],_vagasEntregadoresCache=[],_vagasDiaAberto=null,_vagasMinhaLoja=null;

function _vagasEhFimDeSemanaOuFeriado(dataStr){
  const dow=new Date(dataStr+'T00:00:00').getDay();
  const feriado=_feriadosCache.some(f=>f.data===dataStr);
  return dow===0||dow===6||feriado;
}
function _vagasCalcularValor(dataStr){
  return _vagasEhFimDeSemanaOuFeriado(dataStr)?40:30;
}

async function renderVagasPage(){
  const hoje=new Date();
  _vagasAno=hoje.getFullYear();_vagasMes=hoje.getMonth();
  document.getElementById('app-body').innerHTML=`<div class="alt-page">
    <div class="page-header"><div class="page-title">${_icone('calendar-days',22)} ${currentPerfil==='suporte'?'Solicitar Fixo':'Entrega Dedicada'}</div>${currentPerfil==='adm'?`<button class="btn-sm btn-primary-sm" onclick="_vagasAbrirFeriados()">${_icone('calendar',16,'btn-ico')}Gerenciar Feriados</button>`:''}</div>
    <div class="card"><div style="padding:16px 20px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px">
        <button onclick="_vagasMudarMes(-1)" style="background:var(--surface2);border:1px solid var(--border);border-radius:8px;width:32px;height:32px;cursor:pointer;font-size:16px;color:var(--text)">‹</button>
        <div id="vagas-mes-label" style="font-size:16px;font-weight:700;color:var(--text)">—</div>
        <button onclick="_vagasMudarMes(1)" style="background:var(--surface2);border:1px solid var(--border);border-radius:8px;width:32px;height:32px;cursor:pointer;font-size:16px;color:var(--text)">›</button>
      </div>
      <div id="vagas-calendario"><div style="padding:32px;text-align:center;color:var(--text3)">Carregando...</div></div>
      <div style="display:flex;gap:16px;margin-top:14px;font-size:11px;color:var(--text3)">
        <div style="display:flex;align-items:center;gap:5px"><span style="width:9px;height:9px;border-radius:50%;background:#22c55e;display:inline-block"></span> Tem Vaga Disponível</div>
        <div style="display:flex;align-items:center;gap:5px"><span style="width:9px;height:9px;border-radius:50%;background:#6b7280;display:inline-block"></span> Só Vagas Preenchidas</div>
      </div>
    </div></div>
    <div class="card" id="vagas-dia-painel" style="margin-top:16px"></div>
  </div>`;
  _vagasDiaAberto=_dataHojeBrasilia(); // abre com o dia de hoje selecionado
  if(currentPerfil!=='loja'){
    _vagasLojas=await db('lojas','GET',null,'?ativo=eq.true&select=id,nome,endereco&order=nome.asc');
  } else {
    const minhaLoja=await db('lojas','GET',null,`?id=eq.${currentUser?.loja_id}&select=id,endereco`);
    _vagasMinhaLoja=Array.isArray(minhaLoja)&&minhaLoja[0]?minhaLoja[0]:null;
  }
  await _vagasCarregarMes();
}

function _vagasMudarMes(delta){
  _vagasMes+=delta;
  if(_vagasMes<0){_vagasMes=11;_vagasAno--;}
  if(_vagasMes>11){_vagasMes=0;_vagasAno++;}
  const pref=`${_vagasAno}-${String(_vagasMes+1).padStart(2,'0')}-`,hoje=_dataHojeBrasilia();
  if(!(_vagasDiaAberto||'').startsWith(pref))_vagasDiaAberto=hoje.startsWith(pref)?hoje:pref+'01';
  _vagasCarregarMes();
}

async function _vagasCarregarMes(){
  const cal=document.getElementById('vagas-calendario');if(!cal)return;
  cal.innerHTML='<div style="padding:32px;text-align:center;color:var(--text3)">Carregando...</div>';
  const primeiroDia=`${_vagasAno}-${String(_vagasMes+1).padStart(2,'0')}-01`;
  const ultimoDiaNum=new Date(_vagasAno,_vagasMes+1,0).getDate();
  const ultimoDia=`${_vagasAno}-${String(_vagasMes+1).padStart(2,'0')}-${String(ultimoDiaNum).padStart(2,'0')}`;
  const [vagas,feriados]=await Promise.all([
    db('vagas_motoboy_fixo','GET',null,`?data=gte.${primeiroDia}&data=lte.${ultimoDia}${_lojaFiltro()}&order=data.asc`),
    db('feriados_importantes','GET',null,'')
  ]);
  _vagasDoMes=Array.isArray(vagas)?vagas:[];
  _feriadosCache=Array.isArray(feriados)?feriados:[];
  const idsEntregadores=[...new Set(_vagasDoMes.filter(v=>v.entregador_id).map(v=>v.entregador_id))];
  _vagasEntregadoresCache=idsEntregadores.length?await db('entregadores','GET',null,`?id=in.(${idsEntregadores.join(',')})&select=id,nome`):[];
  const meses=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
  const lbl=document.getElementById('vagas-mes-label');if(lbl)lbl.textContent=`${meses[_vagasMes]} ${_vagasAno}`;
  _vagasRenderCalendario();
  if(_vagasDiaAberto)_vagasAbrirDia(_vagasDiaAberto,true);
}

function _vagasRenderCalendario(){
  const cal=document.getElementById('vagas-calendario');if(!cal)return;
  const primeiroDiaSemana=new Date(_vagasAno,_vagasMes,1).getDay();
  const totalDias=new Date(_vagasAno,_vagasMes+1,0).getDate();
  const porDia={};
  _vagasDoMes.forEach(v=>{(porDia[v.data]=porDia[v.data]||[]).push(v);});
  const diasSemana=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
  let html=`<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:4px">`;
  diasSemana.forEach(d=>{html+=`<div style="text-align:center;font-size:11px;font-weight:700;color:var(--text3);padding:6px 0">${d}</div>`;});
  for(let i=0;i<primeiroDiaSemana;i++){html+=`<div></div>`;}
  for(let dia=1;dia<=totalDias;dia++){
    const dataStr=`${_vagasAno}-${String(_vagasMes+1).padStart(2,'0')}-${String(dia).padStart(2,'0')}`;
    const vagasDoDia=(porDia[dataStr]||[]).filter(v=>v.status!=='cancelada'); // cancelada não conta no calendário (aparece no painel do dia)
    const temDisponivel=vagasDoDia.some(v=>v.status==='disponivel');
    const temAlguma=vagasDoDia.length>0;
    const cor=temDisponivel?'#22c55e':temAlguma?'#6b7280':'transparent';
    const ehFeriado=_feriadosCache.some(f=>f.data===dataStr);
    const sel=dataStr===_vagasDiaAberto,ehHoje=dataStr===_dataHojeBrasilia();
    html+=`<div onclick="_vagasAbrirDia('${dataStr}')" data-dia="${dataStr}" style="cursor:pointer;border:${sel?'2px solid var(--accent)':'1px solid var(--border)'};border-radius:8px;padding:${sel?'7px 3px':'8px 4px'};min-height:56px;background:${sel?'rgba(26,86,219,.16)':'var(--surface2)'};position:relative;text-align:center">
      <div style="font-size:13px;font-weight:${sel||ehHoje?800:600};color:${ehFeriado?'#f59e0b':sel?'var(--accent)':'var(--text)'}">${dia}${ehHoje?'<div style="font-size:9px;font-weight:700;color:var(--accent);letter-spacing:.3px">Hoje</div>':''}</div>
      ${temAlguma?`<div style="margin-top:4px;display:flex;justify-content:center;align-items:center;gap:3px"><span style="width:8px;height:8px;border-radius:50%;background:${cor};display:inline-block"></span><span style="font-size:10px;color:var(--text3)">${vagasDoDia.length}</span></div>`:''}
    </div>`;
  }
  html+=`</div>`;
  cal.innerHTML=html;
}

function _vagasRenderCard(v){
  const loja=_vagasLojas.find(l=>l.id===v.loja_id)||allLojas.find(l=>l.id===v.loja_id);
  const entregador=_vagasEntregadoresCache.find(e=>e.id===v.entregador_id);
  const _selo=(fundo,cor,txt)=>`<span style="background:${fundo};color:${cor};padding:2px 8px;border-radius:20px;font-size:11px;font-weight:700;white-space:nowrap">${txt}</span>`;
  const badge=v.status==='preenchida'?_selo('#dbeafe','#1d4ed8','Preenchida'):v.status==='finalizada'?_selo('#e5e7eb','#374151','Finalizada'):v.status==='cancelada'?_selo('#fee2e2','#b91c1c','Cancelada'):_selo('#d1fae5','#059669','Disponível');
  return `<div style="background:var(--surface2);border-radius:8px;padding:12px;margin-bottom:10px">
    <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:6px;gap:8px">
      <div>
        ${currentPerfil!=='loja'?`<div style="font-size:13px;font-weight:700;color:var(--text)">${loja?.nome||'—'}</div>`:''}
        <div style="font-size:12px;color:var(--text2)">${v.endereco||'—'}</div>
        <div style="font-size:12px;color:var(--text3)">${(v.horario_inicio||'').slice(0,5)} - ${(v.horario_fim||'').slice(0,5)} · R$ ${parseFloat(v.valor).toFixed(2)}</div>
        ${v.status==='preenchida'?`<div style="font-size:12px;color:#1d4ed8;font-weight:600;margin-top:4px;display:flex;align-items:center;gap:5px">${_icone('bike',14)} ${entregador?.nome||'Motoboy Alocado'}</div>`:''}
      </div>
      ${badge}
    </div>
    ${_vagasAcoesHtml(v)}
  </div>`;
}

// Painel do dia (2026-09-29): antes era um modal (#modal-vagas-dia); agora o
// conteúdo fica na própria tela, abaixo do calendário. Mesma lógica de
// criação (_vagasSalvar), preço (_vagasCalcularValor) e alocação. Dia
// passado: mostra as vagas mas desabilita o formulário ("Dia já passou").
// semRolar=true quando é só um re-render (troca de mês / após salvar).
function _vagasAbrirDia(dataStr,semRolar){
  _vagasDiaAberto=dataStr;
  const painel=document.getElementById('vagas-dia-painel');if(!painel)return;
  document.querySelectorAll('#vagas-calendario [data-dia]').forEach(el=>{const sel=el.dataset.dia===dataStr;el.style.border=sel?'2px solid var(--accent)':'1px solid var(--border)';el.style.padding=sel?'7px 3px':'8px 4px';el.style.background=sel?'rgba(26,86,219,.16)':'var(--surface2)';const n=el.firstElementChild;if(n&&!_feriadosCache.some(f=>f.data===el.dataset.dia))n.style.color=sel?'var(--accent)':'var(--text)';});
  const [ano,mes,dia]=dataStr.split('-');
  const passado=dataStr<_dataHojeBrasilia();
  const diasSem=['domingo','segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado'];
  const dow=diasSem[new Date(Date.UTC(+ano,+mes-1,+dia)).getUTCDay()];
  const vagasDoDia=_vagasDoMes.filter(v=>v.data===dataStr);
  const lojaOpts=currentPerfil==='loja'?'':`<select id="vg-loja" style="${_scInput()}" onchange="_vagasAtualizarEnderecoLoja()"><option value="">Selecione A Loja...</option>${_vagasLojas.map(l=>`<option value="${l.id}" data-endereco="${(l.endereco||'').replace(/"/g,'&quot;')}">${l.nome}</option>`).join('')}</select>`;
  const enderecoValor=currentPerfil==='loja'?(_vagasMinhaLoja?.endereco||''):'';
  const valorPrevia=_vagasCalcularValor(dataStr);
  const periodo=(id,icone,nome,hora)=>`<label class="vg-periodo" for="${id}"><input type="checkbox" id="${id}"/><span class="vg-periodo-caixa">${_icone('check',14)}</span><span class="vg-periodo-icone">${_icone(icone,18)}</span><span class="vg-periodo-texto"><span class="vg-periodo-nome">${nome}</span><span class="vg-periodo-hora">${hora}</span></span></label>`;
  painel.innerHTML=`<div style="padding:18px 20px">
      <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px">
        <span style="color:var(--accent);display:inline-flex">${_icone('calendar-days',20)}</span>
        <div style="font-size:16px;font-weight:800;color:var(--text)">${dia}/${mes}/${ano}</div>
        <div style="font-size:12.5px;color:var(--text3)">${dow.replace(/^./,c=>c.toUpperCase())}</div>
        ${passado?`<span style="margin-left:auto;font-size:11px;font-weight:700;color:var(--text3);background:var(--surface2);border:1px solid var(--border);border-radius:20px;padding:3px 10px">Dia Já Passou</span>`:''}
      </div>
      <div class="vg-painel-grid">
        <div>
          <div style="font-size:12px;font-weight:700;color:var(--text2);text-transform:uppercase;letter-spacing:.6px;margin-bottom:10px">Vagas do dia${vagasDoDia.length?` (${vagasDoDia.length})`:''}</div>
          <div id="vg-lista-dia">${vagasDoDia.length?vagasDoDia.map(v=>_vagasRenderCard(v)).join(''):'<div style="color:var(--text3);font-size:13px;padding:14px;background:var(--surface2);border-radius:8px">Nenhuma Vaga Cadastrada Nesse Dia Ainda.</div>'}</div>
        </div>
        <div class="vg-form${passado?' vg-form-bloqueado':''}">
          <div style="font-size:12px;font-weight:700;color:var(--text2);text-transform:uppercase;letter-spacing:.6px;margin-bottom:10px;display:flex;align-items:center;gap:6px">${_icone('plus',14)} Nova Vaga Em ${dia}/${mes}/${ano}</div>
          ${passado?`<div style="display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text2);background:var(--surface2);border:1px solid var(--border);border-radius:8px;padding:10px 12px;margin-bottom:12px">${_icone('lock',16)} Dia Já Passou — Não É Possível Criar Vagas Nesta Data.</div>`:''}
          <fieldset ${passado?'disabled':''} style="border:none;padding:0;margin:0;min-width:0">
            ${currentPerfil!=='loja'?`<div class="fi" style="margin-bottom:10px"><label>Loja</label>${lojaOpts}</div>`:''}
            <div class="fi" style="margin-bottom:10px"><label>Endereço</label><input type="text" id="vg-endereco" value="${enderecoValor}" disabled placeholder="${currentPerfil==='loja'?'':'Selecione A Loja Acima'}" style="${_scInput()};opacity:.7"/></div>
            <div class="fi" style="margin-bottom:10px"><label>Período</label>
              <div class="vg-periodos">${periodo('vg-periodo-almoco','sun','Almoço','10:00–14:00')}${periodo('vg-periodo-jantar','moon','Jantar','18:00–23:59')}</div>
            </div>
            <div class="fi" style="margin-bottom:14px"><label>Valor (Calculado Automaticamente, Por Vaga)</label><input type="text" value="R$ ${valorPrevia.toFixed(2)}" disabled style="${_scInput()};opacity:.7"/></div>
            <button onclick="_vagasSalvar('${dataStr}')" style="background:var(--accent);color:#fff;border:none;border-radius:8px;padding:10px 20px;font-size:13px;font-weight:700;cursor:${passado?'not-allowed':'pointer'};width:100%;opacity:${passado?.5:1};display:inline-flex;align-items:center;justify-content:center">${_icone('check',16,'btn-ico')}Criar Vaga</button>
          </fieldset>
          <div id="vg-feedback" style="margin-top:8px;font-size:13px"></div>
        </div>
      </div>
    </div>`;
  if(!semRolar&&window.innerWidth<700)painel.scrollIntoView({behavior:'smooth',block:'start'});
}

function _vagasAtualizarEnderecoLoja(){
  const sel=document.getElementById('vg-loja');
  const opt=sel?.selectedOptions?.[0];
  const campo=document.getElementById('vg-endereco');
  if(campo)campo.value=opt?.dataset.endereco||'';
}

async function _vagasSalvar(dataStr){
  const fb=document.getElementById('vg-feedback');
  const lojaId=currentPerfil==='loja'?currentUser?.loja_id:document.getElementById('vg-loja')?.value;
  const endereco=(document.getElementById('vg-endereco')?.value||'').trim();
  const almoco=document.getElementById('vg-periodo-almoco')?.checked;
  const jantar=document.getElementById('vg-periodo-jantar')?.checked;
  if(!lojaId||!endereco||(!almoco&&!jantar)){if(fb)fb.innerHTML='<span style="color:#ef4444">Preencha Todos Os Campos E Marque Ao Menos Um Período.</span>';return;}
  const valor=_vagasCalcularValor(dataStr);
  const periodos=[];
  if(almoco)periodos.push({horario_inicio:'10:00',horario_fim:'14:00'});
  if(jantar)periodos.push({horario_inicio:'18:00',horario_fim:'23:59'});
  if(fb)fb.innerHTML='<span style="color:var(--text3)">Salvando...</span>';
  let erro=false;
  for(const p of periodos){
    const payload={loja_id:lojaId,data:dataStr,endereco,horario_inicio:p.horario_inicio,horario_fim:p.horario_fim,valor,status:'disponivel'};
    const res=await db('vagas_motoboy_fixo','POST',payload);
    if(!res||res.length===0)erro=true;
  }
  if(!erro){
    if(fb)fb.innerHTML=`<span style="color:#22c55e">✅ ${periodos.length>1?'Vagas Criadas!':'Vaga Criada!'}</span>`;
    await _vagasCarregarMes(); // re-renderiza calendário e painel do dia
  } else {
    if(fb)fb.innerHTML='<span style="color:#ef4444">❌ Erro Ao Criar Vaga.</span>';
  }
}

// Ações da vaga (2026-09-29): 4 botões sempre visíveis; os que não valem no
// status/dia ficam desabilitados com o motivo no title. Regra aprovada:
//   disponível hoje/futuro: Alocar, Cancelar   | disponível passado: Cancelar
//   preenchida futuro: Desatribuir, Cancelar   | preenchida hoje: Desatribuir, Finalizar, Cancelar
//   preenchida passado: Finalizar, Cancelar    | finalizada/cancelada: nenhum
// Vale pros 3 perfis (loja só vê as vagas dela — _lojaFiltro). Cada ação
// grava em logs_acoes (logAcao) e, se havia entregador, avisa por push
// (edge function notify-vaga).
function _vagasRegraAcoes(v){
  const hoje=_dataHojeBrasilia(),passado=v.data<hoje,ehHoje=v.data===hoje;
  const fechada=v.status==='finalizada'||v.status==='cancelada';
  const livre=v.status==='disponivel',ocupada=v.status==='preenchida';
  const motivoFechada=v.status==='finalizada'?'Vaga Já Finalizada':'Vaga Já Cancelada';
  return {
    alocar:livre&&!passado?null:fechada?motivoFechada:ocupada?'Vaga Já Tem Entregador':'Dia Já Passou',
    desatribuir:ocupada&&!passado?null:fechada?motivoFechada:livre?'Vaga Sem Entregador':'Dia Já Passou',
    finalizar:ocupada&&(passado||ehHoje)?null:fechada?motivoFechada:livre?'Vaga Sem Entregador':'Só No Dia Da Vaga Ou Depois',
    cancelar:fechada?motivoFechada:null,
  };
}
function _vagasAcoesHtml(v){
  const r=_vagasRegraAcoes(v);
  const b=(chave,icone,txt,fn,cor)=>{const bloq=r[chave];return `<button class="vg-acao${cor?' vg-acao-'+cor:''}" ${bloq?`disabled title="${bloq}"`:`onclick="${fn}('${v.id}')" title="${txt}"`}>${_icone(icone,15,'btn-ico')}${txt}</button>`;};
  return `<div class="vg-acoes">${b('alocar','user-plus','Alocar Entregador','_vagasAbrirAlocar','azul')}${b('desatribuir','user-minus','Desatribuir','_vagasDesatribuir')}${b('finalizar','circle-check','Finalizar Vaga','_vagasFinalizar','verde')}${b('cancelar','circle-x','Cancelar Vaga','_vagasCancelar','vermelho')}</div>`;
}
async function _vagasMudarStatus(vagaId,acao){
  const v=_vagasDoMes.find(x=>x.id===vagaId);if(!v)return;
  if(_vagasRegraAcoes(v)[acao]){showNotif('Ação Indisponível',_vagasRegraAcoes(v)[acao],'var(--yellow)');return;}
  const [ano,mes,dia]=v.data.split('-');const quando=`${dia}/${mes} ${(v.horario_inicio||'').slice(0,5)}–${(v.horario_fim||'').slice(0,5)}`;
  const txt={desatribuir:`Tirar o entregador da vaga de ${quando}? Ela volta a ficar disponível.`,finalizar:`Finalizar a vaga de ${quando} como cumprida?`,cancelar:`Cancelar a vaga de ${quando}?${v.entregador_id?' O entregador será avisado.':''}`}[acao];
  if(!confirm(txt))return;
  // condição de status no filtro: não sobrescreve se a vaga mudou em outra tela
  const de={desatribuir:'preenchida',finalizar:'preenchida',cancelar:v.status}[acao];
  const para={desatribuir:{status:'disponivel',entregador_id:null},finalizar:{status:'finalizada'},cancelar:{status:'cancelada'}}[acao];
  const res=await dbPatch('vagas_motoboy_fixo',{...para,updated_at:new Date().toISOString()},`?id=eq.${vagaId}&status=eq.${de}`);
  if(res===null){showNotif('❌ Erro Ao Atualizar A Vaga','','var(--red)');return;}
  if(Array.isArray(res)&&!res.length){showNotif('⚠️ A Vaga Mudou','Atualizando A Lista…','var(--yellow)');await _vagasCarregarMes();return;}
  await logAcao('vaga_'+acao,{vaga_id:vagaId,loja_id:v.loja_id,data:v.data,horario:`${(v.horario_inicio||'').slice(0,5)}-${(v.horario_fim||'').slice(0,5)}`,status_anterior:v.status,entregador_id:v.entregador_id||null});
  if(v.entregador_id&&(acao==='desatribuir'||acao==='cancelar')){
    fetch(`${SB_URL}/functions/v1/notify-vaga`,{method:'POST',headers:{'Content-Type':'application/json','x-webhook-secret':'letsgo2026secret'},body:JSON.stringify({vaga_id:vagaId,entregador_id:v.entregador_id,acao:acao==='cancelar'?'cancelada':'desatribuida'})})
      .then(r=>{if(!r.ok)console.warn('[notify-vaga] HTTP',r.status);}).catch(e=>console.warn('[notify-vaga]',e));
  }
  showNotif({desatribuir:'✅ Entregador Removido Da Vaga',finalizar:'✅ Vaga Finalizada',cancelar:'🗑️ Vaga Cancelada'}[acao],'',acao==='cancelar'?'var(--red)':'var(--green)');
  await _vagasCarregarMes();
}
function _vagasDesatribuir(id){return _vagasMudarStatus(id,'desatribuir');}
function _vagasFinalizar(id){return _vagasMudarStatus(id,'finalizar');}
function _vagasCancelar(id){return _vagasMudarStatus(id,'cancelar');}

function _vagasAbrirAlocar(vagaId){
  let modal=document.getElementById('modal-vagas-alocar');
  if(!modal){modal=document.createElement('div');modal.id='modal-vagas-alocar';modal.className='modal-overlay';document.body.appendChild(modal);}
  modal.innerHTML=`<div class="modal" style="max-width:420px">
    <div class="modal-header"><span class="modal-title">${_icone('user-plus',18)} Alocar Entregador</span><button class="modal-close" onclick="document.getElementById('modal-vagas-alocar').classList.remove('open')">${_icone('x',16)}</button></div>
    <div class="modal-body">
      <div class="fi" style="margin-bottom:12px"><label>CPF Do Motoboy</label><input type="text" id="va-cpf" placeholder="000.000.000-00" style="${_scInput()}"/></div>
      <button onclick="_vagasBuscarCpf('${vagaId}')" style="width:100%;background:var(--surface2);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:9px;font-size:13px;font-weight:600;cursor:pointer">${_icone('search',16,'btn-ico')}Buscar</button>
      <div id="va-resultado" style="margin-top:14px"></div>
    </div>
  </div>`;
  modal.classList.add('open');
}

async function _vagasBuscarCpf(vagaId){
  const cpfDigitado=(document.getElementById('va-cpf')?.value||'').trim();
  const resultado=document.getElementById('va-resultado');
  if(!cpfDigitado){if(resultado)resultado.innerHTML='<span style="color:#ef4444;font-size:13px">Digite Um CPF.</span>';return;}
  if(resultado)resultado.innerHTML='<span style="color:var(--text3);font-size:13px">Buscando...</span>';
  const cpfSoDigitos=cpfDigitado.replace(/\D/g,'');
  // Compara com e sem formatação, mesmo critério já usado no app entregador
  // pra checar CPF duplicado — cobre qualquer padrão gravado no banco.
  const rows=await db('entregadores','GET',null,`?or=(cpf.eq.${encodeURIComponent(cpfDigitado)},cpf.eq.${cpfSoDigitos})&select=id,nome,cpf,modal_veiculo&limit=1`);
  const ent=Array.isArray(rows)&&rows[0]?rows[0]:null;
  if(!ent){if(resultado)resultado.innerHTML='<span style="color:#ef4444;font-size:13px">Nenhum Entregador Encontrado Com Esse CPF.</span>';return;}
  if((ent.modal_veiculo||'').toLowerCase()!=='moto'){
    resultado.innerHTML=`<div style="background:#fef2f2;border:1px solid #fecaca;color:#b91c1c;border-radius:8px;padding:10px;font-size:13px"><b>${ent.nome}</b> Encontrado, Mas Não Está Cadastrado Com Moto (Veículo: ${ent.modal_veiculo||'—'}).<br>Vagas Fixas Exigem Motoboy De Moto — Alocação Bloqueada.</div>`;
    return;
  }
  resultado.innerHTML=`<div style="background:var(--surface2);border-radius:8px;padding:10px;margin-bottom:10px"><div style="font-size:13px;color:var(--text3)">Encontrado:</div><div style="font-size:15px;font-weight:700;color:var(--text)">${ent.nome}</div></div>
    <button onclick="_vagasConfirmarAlocar('${vagaId}','${ent.id}')" style="width:100%;background:#22c55e;color:#fff;border:none;border-radius:8px;padding:9px;font-size:13px;font-weight:700;cursor:pointer">${_icone('check',16,'btn-ico')}Confirmar Alocação</button>`;
}

async function _vagasConfirmarAlocar(vagaId,entregadorId){
  const res=await dbPatch('vagas_motoboy_fixo',{status:'preenchida',entregador_id:entregadorId,updated_at:new Date().toISOString()},`?id=eq.${vagaId}`);
  if(res===null){showNotif('❌ Erro Ao Alocar','','var(--red)');return;}
  showNotif('✅ Entregador Alocado!','');
  document.getElementById('modal-vagas-alocar')?.classList.remove('open');
  await _vagasCarregarMes();
  if(_vagasDiaAberto)_vagasAbrirDia(_vagasDiaAberto,true);
}

// Só admin (2026-09-29): feriados_importantes é global (sem loja_id) e
// define o preço da vaga (R$40 feriado/fim de semana, R$30 senão — ver
// _vagasCalcularValor); loja/suporte não podem mexer. Guarda aqui também
// além de esconder o botão em renderVagasPage. Obs.: a tabela está com RLS
// ligada e sem política (nem o admin grava) — correção de RLS pendente.
async function _vagasAbrirFeriados(){
  if(currentPerfil!=='adm')return;
  let modal=document.getElementById('modal-feriados');
  if(!modal){modal=document.createElement('div');modal.id='modal-feriados';modal.className='modal-overlay';document.body.appendChild(modal);}
  modal.innerHTML=`<div class="modal" style="max-width:480px">
    <div class="modal-header"><span class="modal-title">${_icone('calendar',18)} Feriados Importantes</span><button class="modal-close" onclick="document.getElementById('modal-feriados').classList.remove('open')">${_icone('x',16)}</button></div>
    <div class="modal-body" style="max-height:70vh;overflow-y:auto">
      <div style="display:flex;gap:10px;margin-bottom:14px;align-items:flex-end">
        <div class="fi" style="flex:1"><label>Data</label><input type="date" id="fer-data" style="${_scInput()}"/></div>
        <div class="fi" style="flex:1"><label>Descrição (Opcional)</label><input type="text" id="fer-descricao" placeholder="Ex: Natal" style="${_scInput()}"/></div>
      </div>
      <button onclick="_feriadoSalvar()" style="width:100%;background:var(--accent);color:#fff;border:none;border-radius:8px;padding:9px;font-size:13px;font-weight:700;cursor:pointer;margin-bottom:16px">${_icone('plus',16,'btn-ico')}Adicionar</button>
      <div id="fer-lista"></div>
    </div>
  </div>`;
  modal.classList.add('open');
  await _feriadosBuscar();
}

async function _feriadosBuscar(){
  const rows=await db('feriados_importantes','GET',null,'?order=data.asc');
  _feriadosCache=Array.isArray(rows)?rows:[];
  const lista=document.getElementById('fer-lista');if(!lista)return;
  if(!_feriadosCache.length){lista.innerHTML='<div style="color:var(--text3);font-size:13px">Nenhum Feriado Cadastrado.</div>';return;}
  lista.innerHTML=_feriadosCache.map(f=>{
    const [ano,mes,dia]=f.data.split('-');
    return `<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid var(--border)">
      <div><span style="font-weight:700;color:var(--text)">${dia}/${mes}/${ano}</span>${f.descricao?` <span style="color:var(--text3);font-size:12px">— ${f.descricao}</span>`:''}</div>
      <button onclick="_feriadoExcluir('${f.id}')" style="background:none;border:1px solid #ef4444;border-radius:6px;width:26px;height:26px;cursor:pointer;font-size:12px">${_icone('trash-2',16)}</button>
    </div>`;
  }).join('');
}

async function _feriadoSalvar(){
  const data=document.getElementById('fer-data')?.value;
  const descricao=(document.getElementById('fer-descricao')?.value||'').trim()||null;
  if(!data){showNotif('Atenção','Selecione Uma Data','var(--yellow)');return;}
  const res=await db('feriados_importantes','POST',{data,descricao});
  if(!res||!res.length){showNotif('❌ Erro','Data Já Cadastrada Ou Inválida','var(--red)');return;}
  document.getElementById('fer-data').value='';document.getElementById('fer-descricao').value='';
  await _feriadosBuscar();
  if(document.getElementById('vagas-calendario'))_vagasRenderCalendario();
}

async function _feriadoExcluir(id){
  if(!confirm('Excluir Esse Feriado?'))return;
  await db('feriados_importantes','DELETE',null,`?id=eq.${id}`);
  await _feriadosBuscar();
  if(document.getElementById('vagas-calendario'))_vagasRenderCalendario();
}

async function _buscarFinanceiro(){
  const e1=document.getElementById('fin-faturamento'),e2=document.getElementById('fin-despesas'),e3=document.getElementById('fin-lucro'),e4=document.getElementById('fin-mercadoria');
  if(e1)e1.textContent='...';if(e2)e2.textContent='...';if(e3)e3.textContent='...';if(e4)e4.textContent='...';
  const [cobrancas,saques,creditos,pedidos]=await Promise.all([
    db('cobrancas_lojas','GET',null,'?select=id,valor_total&status=in.(pago,aprovado)'),
    db('saques','GET',null,'?select=valor_liquido,valor&status=eq.pago'),
    db('creditos_lojas','GET',null,'?select=valor&tipo=eq.credito'),
    db('pedidos','GET',null,'?select=valor&status=eq.finalizado'),
  ]);
  const seen=new Set();
  const fatCobrancas=(Array.isArray(cobrancas)?cobrancas:[]).reduce((s,r)=>{if(seen.has(r.id))return s;seen.add(r.id);return s+(parseFloat(r.valor_total)||0);},0);
  const fatCreditos=(Array.isArray(creditos)?creditos:[]).reduce((s,r)=>s+(parseFloat(r.valor)||0),0);
  const faturamento=fatCobrancas+fatCreditos;
  const despesas=(Array.isArray(saques)?saques:[]).reduce((s,r)=>s+(parseFloat(r.valor_liquido||r.valor)||0),0);
  const lucro=faturamento-despesas;
  const mercadoria=(Array.isArray(pedidos)?pedidos:[]).reduce((s,r)=>s+(parseFloat(r.valor)||0),0);
  if(e1)e1.textContent=`R$ ${faturamento.toFixed(2)}`;
  if(e2)e2.textContent=`R$ ${despesas.toFixed(2)}`;
  if(e3){e3.textContent=`R$ ${Math.abs(lucro).toFixed(2)}`;e3.style.color=lucro>=0?'var(--green)':'var(--red)';}
  if(e4)e4.textContent=`R$ ${mercadoria.toFixed(2)}`;
}

async function _carregarResumoFinanceiro(){
  const hojeBrStr=_dataHojeBrasilia();
  const hojeBrParts=hojeBrStr.split('-').map(Number);
  const hojeBrUtc=new Date(Date.UTC(hojeBrParts[0],hojeBrParts[1]-1,hojeBrParts[2]));
  const dow=hojeBrUtc.getUTCDay();
  const diff=dow===0?6:dow-1;
  hojeBrUtc.setUTCDate(hojeBrUtc.getUTCDate()-diff);
  const startSemanaISO=_inicioDiaBrasilia(hojeBrUtc.toISOString().slice(0,10));

  const _lf=_lojaFiltro();
  const [cobrancasPagas,saquesPagos,saquesPendentes]=await Promise.all([
    db('cobrancas_lojas','GET',null,`?select=valor_total&status=eq.pago&updated_at=gte.${startSemanaISO}${_lf}`),
    db('saques','GET',null,`?select=valor&status=eq.pago&updated_at=gte.${startSemanaISO}`),
    db('saques','GET',null,'?select=valor&status=eq.pendente&chave_pix=is.null'),
  ]);

  const somaValor=arr=>(Array.isArray(arr)?arr:[]).reduce((s,r)=>s+(parseFloat(r.valor)||0),0);
  const somaValorTotal=arr=>(Array.isArray(arr)?arr:[]).reduce((s,r)=>s+(parseFloat(r.valor_total)||0),0);

  const faturamento=somaValorTotal(cobrancasPagas);
  const despesas=somaValor(saquesPagos);
  const lucro=faturamento-despesas;

  _saquesPendentesCount=Array.isArray(saquesPendentes)?saquesPendentes.length:0;
  renderNavSidebar(_navAtivo);
  _buscarFinanceiro();
}

